const schoolAllowedRouteKeys = new Set(["escolaColetiva", "jogos", "biblioteca", "viewer", "colorirDescobrir", "suporte"]);
const decodePlatformJwtPayload = (token) => {
  try {
    const [, payload] = String(token || "").split(".");
    if (!payload) return {};
    const normalized = payload.replaceAll("-", "+").replaceAll("_", "/");
    const padded = `${normalized}${"=".repeat((4 - (normalized.length % 4)) % 4)}`;
    return JSON.parse(atob(padded));
  } catch (error) {
    return {};
  }
};
const normalizePlatformRole = (role) => {
  const normalized = String(role || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase();
  return Object.keys(platformRoles).find((key) => platformRoles[key].includes(normalized)) || normalized;
};
const getPlatformSession = () => {
  try {
    const session = JSON.parse(localStorage.getItem(platformSessionKey) || "null");
    const payload = decodePlatformJwtPayload(session?.access_token || localStorage.getItem("raizes:supabase-access-token") || "");
    const metadata = payload.app_metadata || {};
    const userMetadata = payload.user_metadata || session?.user?.user_metadata || {};
    const role = normalizePlatformRole(
      metadata.platform_role ||
        metadata.app_role ||
        metadata.role ||
        metadata.question_bank_role ||
        payload.platform_role ||
        payload.app_role ||
        userMetadata.platform_role ||
        userMetadata.role ||
        session?.platform_role ||
        session?.question_bank_role
    );
    return {
      userId: payload.sub || session?.user?.id || null,
      email: payload.email || session?.user?.email || "",
      name: userMetadata.full_name || userMetadata.name || session?.user?.email || "",
      role,
      expiresAt: payload.exp || session?.expires_at || 0,
    };
  } catch (error) {
    return { userId: null, email: "", name: "", role: "", expiresAt: 0 };
  }
};
const hasValidPlatformSession = () => {
  const session = getPlatformSession();
  return Boolean(session.userId && session.role && Number(session.expiresAt || 0) > Math.floor(Date.now() / 1000) + 60);
};
const getCurrentPlatformRole = () => {
  const session = getPlatformSession();
  if (hasValidPlatformSession()) {
    return session.role;
  }
  return "";
};
const contentGovernanceConsumerRoles = new Set(["aluno", "educacao_infantil", "escola", "professor"]);
const contentGovernanceRouteKeys = new Set([
  "biblioteca",
  "viewer",
  "jogos",
  "atividades",
  "alunoAtividades",
  "alunoAtividade",
  "professor",
  "professorTurma",
  "professorAluno",
  "escolaColetiva",
  "familia",
]);
const contentGovernanceState = {
  status: "idle",
  schoolIds: [],
  availability: [],
  error: "",
  promise: null,
};
const contentGovernanceEscape = (value) =>
  String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
const normalizeContentGovernanceType = (type = "") => {
  const value = String(type || "").trim().toLowerCase();
  if (["printable_activity", "printable-activity", "atividade", "atividades"].includes(value)) return "activity";
  if (["books", "livro", "livros"].includes(value)) return "book";
  if (["games", "jogo", "jogos"].includes(value)) return "game";
  if (["experiences", "experiência", "experiências"].includes(value)) return "experience";
  return value;
};
const isContentGovernanceRequired = () =>
  hasValidPlatformSession() && contentGovernanceConsumerRoles.has(getCurrentPlatformRole());
const isContentGovernanceReady = () => !isContentGovernanceRequired() || contentGovernanceState.status === "ready";
const isAvailabilityRowActive = (row, now = new Date()) => {
  if (!row || row.deleted_at) return false;
  if (String(row.status || "").toLowerCase() !== "available") return false;
  const from = row.available_from ? new Date(row.available_from) : null;
  const until = row.available_until ? new Date(row.available_until) : null;
  if (from && !Number.isNaN(from.getTime()) && from > now) return false;
  if (until && !Number.isNaN(until.getTime()) && until < now) return false;
  return true;
};
const ensureContentGovernanceData = async ({ force = false } = {}) => {
  if (!isContentGovernanceRequired()) {
    contentGovernanceState.status = "ready";
    contentGovernanceState.schoolIds = [];
    contentGovernanceState.availability = [];
    contentGovernanceState.error = "";
    return contentGovernanceState;
  }
  if (!force && contentGovernanceState.status === "ready") return contentGovernanceState;
  if (!force && contentGovernanceState.promise) return contentGovernanceState.promise;
  contentGovernanceState.status = "loading";
  contentGovernanceState.error = "";
  contentGovernanceState.promise = (async () => {
    try {
      const client = createSupabaseRestClient();
      const schoolsResult = await client.request("rpc/current_institutional_school_ids", "", {
        method: "POST",
        body: JSON.stringify({}),
        requireAuthenticated: true,
        allowedRoles: ["aluno", "educacao_infantil", "escola", "professor", "admin"],
      });
      const schoolIds = (Array.isArray(schoolsResult) ? schoolsResult : [schoolsResult])
        .map((row) => (typeof row === "string" ? row : row?.school_id || row?.id || row))
        .filter(Boolean);
      const availability = schoolIds.length
        ? await client.request(
            "school_content_availability",
            `?select=school_id,content_type,content_id,status,available_from,available_until,deleted_at&school_id=${supabaseIn(schoolIds)}&status=eq.available&deleted_at=is.null&limit=1000`,
            {
              requireAuthenticated: true,
              allowedRoles: ["aluno", "educacao_infantil", "escola", "professor", "admin"],
            }
          )
        : [];
      contentGovernanceState.status = "ready";
      contentGovernanceState.schoolIds = schoolIds;
      contentGovernanceState.availability = Array.isArray(availability) ? availability : [];
      contentGovernanceState.error = "";
    } catch (error) {
      contentGovernanceState.status = "error";
      contentGovernanceState.schoolIds = [];
      contentGovernanceState.availability = [];
      contentGovernanceState.error = error.message || "Não foi possível carregar a disponibilidade de conteúdos.";
    } finally {
      contentGovernanceState.promise = null;
    }
    return contentGovernanceState;
  })();
  return contentGovernanceState.promise;
};
const isContentAvailableToSession = (type, id) => {
  if (!isContentGovernanceRequired()) return true;
  if (!id || contentGovernanceState.status !== "ready") return false;
  const normalizedType = normalizeContentGovernanceType(type);
  const normalizedId = String(id || "");
  const now = new Date();
  return contentGovernanceState.availability.some(
    (row) =>
      normalizeContentGovernanceType(row.content_type) === normalizedType &&
      String(row.content_id || "") === normalizedId &&
      isAvailabilityRowActive(row, now)
  );
};
const filterContentForSession = (items = [], type, getId = (item) => item?.id) =>
  isContentGovernanceRequired() ? items.filter((item) => isContentAvailableToSession(type, getId(item))) : items;
const renderContentGovernanceLoading = (title = "Conteúdos") => `
  <section class="bv-section">
    <div class="panel-head"><h2>${contentGovernanceEscape(title)}</h2><a>carregando</a></div>
    <p class="bv-empty-state">Carregando conteúdos disponíveis para sua escola.</p>
  </section>
`;
const renderContentUnavailableForSchool = ({ title = "Conteúdo indisponível", type = "conteúdo", id = "" } = {}) => `
  <section class="bv-section">
    <div class="panel-head"><h2>${contentGovernanceEscape(title)}</h2><a>${contentGovernanceEscape(type)}</a></div>
    <p class="bv-empty-state">Este conteúdo não está disponível para a sua escola neste momento.</p>
    ${id ? `<p class="bv-empty-state">${contentGovernanceEscape(id)}</p>` : ""}
  </section>
`;
const maybeRefreshContentGovernancePage = (activeKey) => {
  if (!contentGovernanceRouteKeys.has(activeKey) || !isContentGovernanceRequired()) return;
  if (contentGovernanceState.status === "idle") {
    ensureContentGovernanceData().then(() => {
      const mount = document.querySelector("[data-app-page]");
      if (mount?.dataset.appPage === activeKey) renderAppPage();
    });
  }
};
const clearPlatformSession = () => {
  try {
    localStorage.removeItem(platformSessionKey);
    localStorage.removeItem("raizes:supabase-access-token");
    localStorage.removeItem(platformAuth.key);
    localStorage.removeItem(platformAuth.curatorKey);
    Object.keys(localStorage)
      .filter((key) => key.startsWith("sb-") || key.includes("supabase.auth.token"))
      .forEach((key) => localStorage.removeItem(key));
  } catch (error) {
    return null;
  }
  return null;
};
const signOutPlatformSession = async ({ redirectTo } = {}) => {
  const session = getPlatformSession();
  const storedSession = (() => {
    try {
      return JSON.parse(localStorage.getItem(platformSessionKey) || "null");
    } catch (error) {
      return null;
    }
  })();
  try {
    if (window.supabase?.auth?.signOut) {
      await window.supabase.auth.signOut();
    } else if (storedSession?.access_token && window.RAIZES_SUPABASE?.url && window.RAIZES_SUPABASE?.anonKey) {
      await fetch(`${window.RAIZES_SUPABASE.url.replace(/\/$/, "")}/auth/v1/logout`, {
        method: "POST",
        headers: {
          apikey: window.RAIZES_SUPABASE.anonKey,
          Authorization: `Bearer ${storedSession.access_token}`,
        },
      });
    }
  } catch (error) {
    // A limpeza local abaixo garante que o navegador não reaproveite a sessão.
  }
  clearPlatformSession();
  window.location.replace(redirectTo || `${platformRoute("/login.html", "login.html")}?logout=1`);
  return session;
};
const canAccessPlatformRoute = (routeKey, role) => {
  if (role === "admin") return true;
  const allowed = routeAccessRules[routeKey];
  if (!allowed) return true;
  return allowed.includes(role);
};
const getRoleHome = (role) => platformRoleHome[normalizePlatformRole(role)] || platformRoute("/", "index.html");
const getCurrentPageName = () => window.location.pathname.replace(/^\/+/, "").replace(/\/$/, "") || "biblioteca.html";
const getProtectedRouteKeyForPath = () => {
  const normalizedPath = getCurrentPageName();
  if (normalizedPath.startsWith("professor/alunos/")) return "professorAluno";
  if (normalizedPath.startsWith("aluno/atividade/")) return "alunoAtividade";
  return protectedRouteKeyByPage[normalizedPath] || protectedRouteKeyByPage[`${normalizedPath}.html`] || "";
};
const normalizeRequestedPath = (path) => {
  const value = String(path || "").replace(/^\/+/, "");
  if (!value) return "index.html";
  if (value.startsWith("professor/")) return value;
  if (value.startsWith("aluno/")) return value;
  return value.endsWith(".html") ? value : `${value}.html`;
};
const getRoleHomeForCurrentSession = () => getRoleHome(getCurrentPlatformRole());
const normalizePlatformNavigationPath = (value = "") => {
  try {
    const url = new URL(value || window.location.href, window.location.origin);
    const path = normalizeRequestedPath(url.pathname.replace(/^\/+/, "") || "index.html");
    return `${path}${url.search || ""}${url.hash || ""}`;
  } catch (error) {
    return normalizeRequestedPath(String(value || "").split(/[?#]/)[0] || "index.html");
  }
};
const getRouteKeyForNavigationPath = (path = "") => {
  const page = normalizeRequestedPath(String(path || "").split(/[?#]/)[0] || "index.html");
  return protectedRouteKeyByPage[page] || protectedRouteKeyByPage[page.replace(/\.html$/, "")] || routeKeyByHref?.[page] || "";
};
const isLegacyPlatformNavigationPath = (path = "") =>
  platformLegacyPages.has(String(path || "").split(/[?#]/)[0].replace(/^\/+/, ""));
const isOfficialBackTarget = (path = "", role = getCurrentPlatformRole()) => {
  const page = String(path || "").split(/[?#]/)[0].replace(/^\/+/, "");
  if (!page || isLegacyPlatformNavigationPath(page) || page === "login.html" || page === "login" || page === "index.html" || page === "index") {
    return false;
  }
  const routeKey = getRouteKeyForNavigationPath(path);
  return routeKey ? canAccessPlatformRoute(routeKey, role) : false;
};
const readPlatformNavigationStack = () => {
  try {
    const stack = JSON.parse(sessionStorage.getItem(platformNavigationStateKey) || "[]");
    return Array.isArray(stack) ? stack.filter(Boolean) : [];
  } catch (error) {
    return [];
  }
};
const writePlatformNavigationStack = (stack = []) => {
  try {
    sessionStorage.setItem(platformNavigationStateKey, JSON.stringify(stack.slice(-20)));
  } catch (error) {
    return null;
  }
  return null;
};
const rememberCurrentPlatformRoute = () => {
  if (typeof window === "undefined") return;
  const current = normalizePlatformNavigationPath(window.location.href);
  if (!isOfficialBackTarget(current)) return;
  const stack = readPlatformNavigationStack();
  if (stack[stack.length - 1] !== current) {
    stack.push(current);
    writePlatformNavigationStack(stack);
  }
};
const navigateToRoleHome = () => {
  window.location.href = getRoleHomeForCurrentSession();
};
const navigatePlatformBack = () => {
  const current = normalizePlatformNavigationPath(window.location.href);
  const stack = readPlatformNavigationStack();
  while (stack.length && stack[stack.length - 1] === current) stack.pop();
  const previous = [...stack].reverse().find((item) => isOfficialBackTarget(item));
  writePlatformNavigationStack(previous ? stack.slice(0, stack.lastIndexOf(previous) + 1) : stack);
  window.location.href = previous || getRoleHomeForCurrentSession();
};

const showPlatformRedirectState = (message = "Redirecionando para o acesso correto.") => {
  const safeMessage = String(message || "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
  document.documentElement.style.display = "";
  if (document.body) {
    document.body.innerHTML = `
      <main class="platform-auth-redirect">
        <strong>Acesso em verificação</strong>
        <p>${safeMessage}</p>
      </main>
    `;
  }
};

const requirePlatformAuth = () => {
  if (typeof window === "undefined") {
    return;
  }

  const rawPath = window.location.pathname.replace(/^\//, "");
  const currentPath = `${normalizeRequestedPath(rawPath || getCurrentPageName())}${window.location.search}${window.location.hash}`;
  const publicPages = new Set(["universidade.html", "universidade", "index.html", "index", "login.html", "login"]);
  if (publicPages.has(getCurrentPageName())) {
    return;
  }

  const protectedRouteKey = getProtectedRouteKeyForPath();
  const currentRole = getCurrentPlatformRole();
  if (protectedRouteKey) {
    if (!currentRole) {
      showPlatformRedirectState("Validando sua sessão antes de abrir este ambiente.");
      window.location.replace(`${platformAuth.loginPage}?next=${encodeURIComponent(currentPath)}&auth=supabase&reason=role`);
      return;
    }
    if (!canAccessPlatformRoute(protectedRouteKey, currentRole)) {
      showPlatformRedirectState("Seu perfil será direcionado para o ambiente correto.");
      window.location.replace(getRoleHome(currentRole));
      return;
    }
    return;
  }

  const isAuthenticated = localStorage.getItem(platformAuth.key) === "true";
  const isCuratorArea = currentPath.startsWith("curadoria.html");
  const isCurator = localStorage.getItem(platformAuth.curatorKey) === "true";
  if (currentRole) {
    return;
  }
  if (isAuthenticated && (!isCuratorArea || isCurator)) {
    return;
  }

  showPlatformRedirectState("Entre com seu usuário para continuar.");
  window.location.replace(`${platformAuth.loginPage}?next=${encodeURIComponent(currentPath)}`);
};

requirePlatformAuth();

