const profileConstructionCopy = {
  aluno: {
    familia: ["Família", "Este espaco vai receber comunicados e acompanhamento familiar assim que a proxima etapa for liberada."],
  },
  professor: {
    planejamentos: ["Planejamentos", "Este modulo esta reservado para o planejamento pedagógico completo da professora."],
    relatórios: ["Relatórios", "Este modulo esta reservado para indicadores, devolutivas e acompanhamento da turma."],
    avaliações: ["Avaliações", "Este modulo esta reservado para rotinas de avaliação e acompanhamento."],
    mensagens: ["Mensagens", "Este modulo esta reservado para comunicados e devolutivas."],
  },
};

const getProfileViewParam = () => {
  if (typeof window === "undefined") return "";
  return new URLSearchParams(window.location.search).get("view") || "";
};

const renderProfileTopTabs = (role) => {
  const config = profileAccessConfig[role];
  return `
    <nav class="profile-top-tabs" aria-label="Abas de navegação ${config.eyebrow}">
      ${config.tabs.map((tab, index) => `<a class="${index === 0 ? "is-active" : ""}" href="${tab.href}">${tab.label}</a>`).join("")}
    </nav>
  `;
};

const renderProfileSidebar = (role) => {
  const config = profileAccessConfig[role];
  return `
    <aside class="profile-access-sidebar" aria-label="${config.quickTitle}">
      <a class="profile-access-logo" href="${config.homeHref}" aria-label="Voltar ao inicio">
        <img src="logo-app.png" alt="${config.logoAlt}" loading="eager" decoding="async" onerror="this.hidden=true" />
      </a>
      <div class="profile-access-identity">
        <span>${config.eyebrow}</span>
        <strong>${config.name}</strong>
      </div>
      <div class="profile-quick-links">
        <h2>${config.quickTitle}</h2>
        ${config.quick.map((item) => `<a class="profile-quick-link is-${item.tone}" href="${item.href}">${item.label}</a>`).join("")}
      </div>
      <button class="profile-sidebar-logout" type="button" data-platform-logout>Sair</button>
    </aside>
  `;
};

const renderProfileHeader = (role) => {
  const config = profileAccessConfig[role];
  return `
    <header class="profile-access-header" aria-label="Navegação principal">
      <label class="profile-access-search">
        <span>Buscar</span>
        <input type="search" placeholder="${config.search}" />
      </label>
      ${renderProfileTopTabs(role)}
    </header>
  `;
};

const renderProfileConstructionState = (role) => {
  const view = getProfileViewParam();
  const copy = profileConstructionCopy[role]?.[view];
  if (!copy) return "";
  const config = profileAccessConfig[role];
  return `
    <section class="profile-construction-state" aria-label="${copy[0]} em construcao">
      <span>Em construcao</span>
      <h2>${copy[0]}</h2>
      <p>${copy[1]}</p>
      <a href="${config.homeHref}">Voltar ao inicio</a>
    </section>
  `;
};

const renderProfileShell = (role, content) => `
  <section class="profile-platform-page ${role === "professor" ? "professor-profile-page" : "student-profile-page"}">
    <div class="profile-platform-intro">
      <div>
        <span>${profileAccessConfig[role].eyebrow}</span>
        <h1>${profileAccessConfig[role].name}</h1>
      </div>
      <div class="profile-platform-quick" aria-label="${profileAccessConfig[role].quickTitle}">
        ${profileAccessConfig[role].quick.map((item) => `<a class="profile-quick-link is-${item.tone}" href="${item.href}">${item.label}</a>`).join("")}
      </div>
    </div>
    ${renderProfileConstructionState(role)}
    ${content}
  </section>
`;

const getStudentProfileInitials = (name = "") => {
  const parts = String(name || "Aluno").trim().split(/\s+/).filter(Boolean);
  return (parts.length > 1 ? `${parts[0][0]}${parts.at(-1)[0]}` : `${parts[0]?.[0] || "A"}`).toUpperCase();
};

const getStudentGamificationAudit = () => {
  const gameSummary = getStudentGameSummary();
  const progress = studentInstitutionalState.progress || {};
  const medals = progress.medals || [];
  const xpRecords = progress.xpRecords || [];
  return {
    xpEngine: xpRecords.length ? "REAL" : "EMPTY_REAL",
    levelEngine: xpRecords.length ? "REAL" : "EMPTY_REAL",
    achievementsEngine: medals.length ? "REAL" : "EMPTY_REAL",
    knowledgeTreeEngine: "PARTIAL",
    gameProgressCount: gameSummary.completedCount || 0,
  };
};

const renderStudentLegacyProfilePage = () => {
  const content = `
    <section class="student-profile-static-map" aria-label="Perfil visual legado do aluno">
      <img
        src="assets/aluno/perfil-aluno-dashboard.png"
        alt="Perfil visual legado do aluno com medalhas, progresso, conquistas e jogos concluídos"
        loading="eager"
        decoding="async"
        onerror="this.hidden=true"
      />
      ${studentProfileHotspots.map((hotspot) => `<a class="profile-hotspot ${hotspot.className}" href="${hotspot.href}" aria-label="${hotspot.label}"></a>`).join("")}
    </section>
  `;
  return renderProfileShell("aluno", content);
};

const renderStudentProfilePage = () => {
  if (!isStudentInstitutionalMode()) return renderStudentLegacyProfilePage();
  const isBlocked = studentInstitutionalState.status !== "ready";
  const profile = getActiveStudentProfile();
  const gamification = getStudentGamificationAudit();
  const profileContent = isBlocked
    ? `<div data-student-profile-institutional>${renderStudentInstitutionalGate()}</div>`
    : `
      <section class="student-real-profile" data-student-profile-institutional>
        <header class="student-real-profile-hero">
          <div class="student-real-profile-avatar" aria-hidden="true">${getStudentProfileInitials(profile.fullName)}</div>
          <div>
            <span>Meu perfil</span>
            <h2>${printableEscape(profile.fullName)}</h2>
            <p>${printableEscape(profile.className)} · ${printableEscape(profile.schoolName)}</p>
          </div>
          <a href="aluno.html">Voltar ao inicio</a>
        </header>

        <section class="student-real-profile-grid" aria-label="Informações do aluno">
          <article class="student-real-profile-card is-main">
            ${premiumIcon("aluno")}
            <div>
              <span>Aluno</span>
              <strong>${printableEscape(profile.fullName)}</strong>
              <p>Perfil carregado a partir do vinculo escolar autenticado.</p>
            </div>
          </article>
          <article class="student-real-profile-card">
            ${premiumIcon("turmas")}
            <div>
              <span>Turma</span>
              <strong>${printableEscape(profile.className)}</strong>
              <p>Matrícula ativa na escola atual.</p>
            </div>
          </article>
          <article class="student-real-profile-card">
            ${premiumIcon("escola")}
            <div>
              <span>Escola</span>
              <strong>${printableEscape(profile.schoolName)}</strong>
              <p>Ambiente institucional do aluno.</p>
            </div>
          </article>
          <article class="student-real-profile-card">
            ${premiumIcon("professor")}
            <div>
              <span>Professora</span>
              <strong>${printableEscape(profile.teacherName)}</strong>
              <p>Resolvida pelo vinculo ativo da turma.</p>
            </div>
          </article>
        </section>

        <section class="student-real-profile-grid is-progress" aria-label="Progresso e conquistas">
          <article class="student-real-profile-card is-progress-card">
            ${premiumIcon("jogos")}
            <div>
              <span>Progresso</span>
              <strong>${Number(studentInstitutionalState.progress?.xpTotal || 0)} XP</strong>
              <p>${(studentInstitutionalState.progress?.xpRecords || []).length ? `${(studentInstitutionalState.progress?.xpRecords || []).length} registro(s) reais de progresso.` : "Sem registro de XP publicado para este aluno."}</p>
            </div>
          </article>
          <article class="student-real-profile-card is-progress-card">
            ${premiumIcon("premio")}
            <div>
              <span>Conquistas</span>
              <strong>${(studentInstitutionalState.progress?.medals || []).length} conquista(s)</strong>
              <p>${(studentInstitutionalState.progress?.medals || []).length ? (studentInstitutionalState.progress.medals || []).slice(0, 2).map((item) => item.medal?.nome || "Conquista").join(", ") : "Sem conquista publicada para este aluno."}</p>
            </div>
          </article>
          <article class="student-real-profile-card is-progress-card">
            ${premiumIcon("arvore")}
            <div>
              <span>Minha Árvore</span>
              <strong>Espaco preparado</strong>
              <p>A arvore atual permanece acessivel para evoluir com XP e conquistas reais.</p>
            </div>
          </article>
        </section>

        <section class="student-real-profile-actions" aria-label="Acessos do aluno">
          <a href="conteudos-categorias.html">${premiumIcon("biblioteca")}<span>Meus conteúdos</span></a>
          <a href="aluno-atividades.html">${premiumIcon("atividades")}<span>Atividades</span></a>
          <a href="biblioteca.html?from=aluno">${premiumIcon("biblioteca")}<span>Biblioteca</span></a>
          <a href="jogos.html">${premiumIcon("jogos")}<span>Jogos</span></a>
          <a href="arvore.html">${premiumIcon("arvore")}<span>Minha Árvore</span></a>
        </section>

        <section class="student-real-profile-readiness" aria-label="Preparação do perfil">
          <article><strong>Perfil</strong><span>Pronto</span></article>
          <article><strong>Avatar</strong><span>Iniciais institucionais</span></article>
          <article><strong>XP</strong><span>${gamification.xpEngine === "REAL" ? "Pronto" : "Sem dados reais"}</span></article>
          <article><strong>Conquistas</strong><span>${gamification.achievementsEngine === "REAL" ? "Pronto" : "Sem dados reais"}</span></article>
        </section>
      </section>
    `;
  return renderProfileShell("aluno", profileContent);
};

