          p_time_limit_minutes: payload.timeLimitMinutes ? Number(payload.timeLimitMinutes) : null,
          p_max_attempts: Number(payload.maxAttempts || 1),
          p_cycle_name: payload.cycleName || null,
          p_school_year: payload.schoolYear || null,
