const ensureStudentInstitutionalData = async ({ force = false } = {}) => {
  if (!isStudentInstitutionalMode()) return studentInstitutionalState;
  if (!force && studentInstitutionalState.status === "ready") return studentInstitutionalState;
  if (!force && studentInstitutionalState.promise) return studentInstitutionalState.promise;
  studentInstitutionalState.status = "loading";
  studentInstitutionalState.error = "";
  studentInstitutionalState.promise = (async () => {
    try {
      const client = createSupabaseRestClient();
      const context = await client.getContext({ requireAuthenticated: true, allowedRoles: ["aluno", "admin"] });
      const profileRows = await client.request("profiles", `?select=*&id=${supabaseEq(context.userId)}&limit=1`, {
        requireAuthenticated: true,
        allowedRoles: ["aluno", "admin"],
      }).catch(() => []);
      const profile = Array.isArray(profileRows) ? profileRows[0] || null : null;
      const studentContext = await getStudentCanonicalContext(client);
      const student = await client
        .request("students", `?select=*&id=${supabaseEq(studentContext.student_id)}&limit=1`, {
          requireAuthenticated: true,
          allowedRoles: ["aluno", "admin"],
        })
        .then((rows) => (Array.isArray(rows) ? rows[0] || null : null))
        .catch(() => null) || mapStudentFromContext(studentContext);
      const publicUser = null;
      if (!student?.id) {
        throw new Error("Não foi possível identificar o vinculo escolar deste aluno.");
      }
      const enrollmentRows = await client.request(
        "enrollments",
        `?select=*,classes(*),schools(*)&student_id=${supabaseEq(student.id)}&status=eq.active&limit=1`,
        { requireAuthenticated: true, allowedRoles: ["aluno", "admin"] }
      ).catch(() => []);
      const enrollment = (Array.isArray(enrollmentRows) ? enrollmentRows[0] || null : null) || mapStudentEnrollmentFromContext(studentContext);
      const classItem = enrollment?.classes || mapStudentClassFromContext(studentContext);
      const school = enrollment?.schools || mapStudentSchoolFromContext(studentContext);
      if (!enrollment?.id || !classItem?.id || !school?.id) {
        throw new Error("Não foi possível identificar o vinculo escolar deste aluno.");
      }
      const teacherMembershipRows = await client.request(
        "class_teacher_memberships",
        `?select=id,role,status,teachers(id,profile_id,user_id,school_id,status,full_name,email,disciplina)&class_id=${supabaseEq(classItem.id)}&status=eq.active`,
        { requireAuthenticated: true, allowedRoles: ["aluno", "admin"] }
      ).catch(() => []);
      const teachers = (Array.isArray(teacherMembershipRows) ? teacherMembershipRows : [])
        .map((row) => row.teachers)
        .filter((teacher) => teacher?.id);
      const teacherProfileIds = [...new Set(teachers.map((teacher) => teacher.profile_id).filter(Boolean))];
      const teacherProfileRows = teacherProfileIds.length
        ? await client.request(
            "profiles",
            `?select=id,display_name,platform_role,status&id=in.(${teacherProfileIds.map(encodeURIComponent).join(",")})`,
            { requireAuthenticated: true, allowedRoles: ["aluno", "admin"] }
          ).catch(() => [])
        : [];
      const teacherProfilesById = new Map(
        (Array.isArray(teacherProfileRows) ? teacherProfileRows : []).map((profileItem) => [profileItem.id, profileItem])
      );
      const resolvedTeachers = teachers.map((teacher) => ({
        ...teacher,
        profile: teacherProfilesById.get(teacher.profile_id) || null,
      }));
      studentInstitutionalState.weekStartIso = studentInstitutionalState.weekStartIso || familyWeekStartIso();
      studentInstitutionalState.calendarError = "";
      studentInstitutionalState.context = studentContext;
      studentInstitutionalState.profile = profile;
      studentInstitutionalState.publicUser = publicUser;
      studentInstitutionalState.student = student;
      studentInstitutionalState.enrollment = enrollment;
      studentInstitutionalState.classItem = classItem;
      studentInstitutionalState.school = school;
      studentInstitutionalState.teachers = resolvedTeachers;
      studentInstitutionalState.entries = [];
      studentInstitutionalState.agendaEvents = [];
      studentInstitutionalState.messages = [];
      studentInstitutionalState.messagesError = "";
      studentInstitutionalState.recommendationsError = "";
      studentInstitutionalState.recommendations = [];
      studentInstitutionalState.personalSchedule = normalizeStudentPersonalSchedulePayload(null);
      studentInstitutionalState.personalScheduleError = "";
      studentInstitutionalState.progress = { xpRecords: [], medals: [], xpTotal: 0 };
      studentInstitutionalState.progressError = "";
      studentInstitutionalState.secondaryLoadedAt = "";
      studentInstitutionalState.status = "ready";
      const refreshSecondaryData = async () => {
        const [entries, recommendations, messages, progress, personalSchedule] = await Promise.all([
          loadStudentUnifiedCalendarEvents(client, studentInstitutionalState.weekStartIso).catch((error) => {
            studentInstitutionalState.calendarError = error.message || "Não foi possível carregar a Minha Semana.";
            return [];
          }),
          loadStudentTeacherRecommendations(client).catch((error) => {
            studentInstitutionalState.recommendationsError = error.message || "Não foi possível carregar as recomendações.";
            return [];
          }),
          loadStudentCommunicationInbox(client).catch((error) => {
            studentInstitutionalState.messagesError = error.message || "Não foi possível carregar os recados.";
            return [];
          }),
          loadStudentProgressSummary(client).catch((error) => {
            studentInstitutionalState.progressError = error.message || "Não foi possível carregar o progresso.";
            return { xpRecords: [], medals: [], xpTotal: 0 };
          }),
          loadStudentPersonalSchedule(client).catch((error) => {
            studentInstitutionalState.personalScheduleError = error.message || "Não foi possível carregar o horário de aula.";
            return normalizeStudentPersonalSchedulePayload(null);
          }),
        ]);
        studentInstitutionalState.entries = (entries || []).filter((entry) => entry.status === "published");
        studentInstitutionalState.agendaEvents = studentInstitutionalState.entries;
        studentInstitutionalState.recommendations = recommendations || [];
        studentInstitutionalState.messages = messages || [];
        studentInstitutionalState.progress = progress || { xpRecords: [], medals: [], xpTotal: 0 };
        studentInstitutionalState.personalSchedule = personalSchedule;
        studentInstitutionalState.secondaryLoadedAt = new Date().toISOString();
        rerenderStudentInstitutionalSurfaces();
      };
      refreshSecondaryData().catch(() => {});
      return studentInstitutionalState;
    } catch (error) {
      studentInstitutionalState.status = "error";
      studentInstitutionalState.error = error.message || "Não foi possível carregar o aluno institucional.";
      studentInstitutionalState.context = null;
      studentInstitutionalState.student = null;
      studentInstitutionalState.enrollment = null;
      studentInstitutionalState.classItem = null;
      studentInstitutionalState.school = null;
      studentInstitutionalState.teachers = [];
      studentInstitutionalState.progress = { xpRecords: [], medals: [], xpTotal: 0 };
      studentInstitutionalState.progressError = "";
      studentInstitutionalState.entries = [];
      studentInstitutionalState.agendaEvents = [];
      studentInstitutionalState.messages = [];
      studentInstitutionalState.messagesError = "";
      studentInstitutionalState.recommendations = [];
      studentInstitutionalState.recommendationsError = "";
      studentInstitutionalState.personalSchedule = normalizeStudentPersonalSchedulePayload(null);
      studentInstitutionalState.personalScheduleError = "";
      return studentInstitutionalState;
    } finally {
      studentInstitutionalState.promise = null;
    }
  })();
  return studentInstitutionalState.promise;
};

const getActiveStudentProfile = () => {
  if (isStudentInstitutionalMode()) {
    const student = studentInstitutionalState.student || {};
    const profile = studentInstitutionalState.profile || {};
    const fullName = normalizeStudentName(student);
    const displayName = fullName !== "Aluno" ? fullName : normalizeProfileName(profile) || "Aluno";
    const teacherNames = (studentInstitutionalState.teachers || []).map(normalizeStudentTeacherName).filter(Boolean);
    return {
      id: student.id || "",
      name: displayName,
      firstName: displayName.split(/\s+/)[0] || "Aluno",
      fullName: displayName,
      className: normalizeClassName(studentInstitutionalState.classItem || {}) || "Turma",
      schoolName: normalizeSchoolName(studentInstitutionalState.school || {}) || "Escola",
      teacherName: teacherNames.length ? teacherNames.join(", ") : "Professor(a) nao informado(a)",
      avatar: "",
      status: studentInstitutionalState.status,
      error: studentInstitutionalState.error,
    };
  }
  return {
    id: pilotProfiles.student.id,
    name: pilotProfiles.student.name,
    firstName: pilotProfiles.student.name,
    fullName: pilotProfiles.student.fullName,
    className: pilotProfiles.student.className,
    schoolName: "",
    teacherName: "",
    avatar: pilotProfiles.student.avatar,
    status: "fallback",
    error: "",
  };
};

const normalizeStudentSegmentValue = (value = "") =>
  String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim()
    .toLowerCase();

const isStudentEarlyChildhoodContext = () => {
  if (!isStudentInstitutionalMode()) return true;
  const context = studentInstitutionalState.context || {};
  const classItem = studentInstitutionalState.classItem || {};
  const segmentText = [
    context.segment,
    context.age_group,
    context.class_name,
    classItem.age_group,
    classItem.nome,
    classItem.name,
  ]
    .map(normalizeStudentSegmentValue)
    .join(" ");
  if (!segmentText.trim()) return false;
  return segmentText.includes("educacao_infantil") || segmentText.includes("infantil");
};

const mapInstitutionalClass = (classItem = {}, school = null, studentCount = 0) => ({
  id: classItem.id,
  name: normalizeClassName(classItem),
  schoolId: classItem.school_id || school?.id || "",
  schoolName: normalizeSchoolName(school || {}),
  status: normalizeInstitutionalStatus(classItem.status),
  shift: classItem.turno || classItem.shift || "",
  schoolYear: classItem.school_year || "",
  students: studentCount,
});

const mapInstitutionalStudent = (student = {}, classItem = null) => {
  const name = normalizeStudentName(student);
  return {
    id: student.id,
    name,
    fullName: name,
    classId: student.class_id || classItem?.id || "",
    className: normalizeClassName(classItem || {}),
    schoolId: student.school_id || classItem?.schoolId || classItem?.school_id || "",
    status: normalizeInstitutionalStatus(student.status),
    avatar: "",
    progress: 0,
    pendingActivities: 0,
    completedActivities: 0,
  };
};

const ensureTeacherInstitutionalData = async ({ force = false } = {}) => {
  const requestedSchool = getPrintableParams().get("school") || "";
  const actor = getTeacherAttendanceActor();
  const requestKey = `${actor}:${getPrintableParams().has("school") ? requestedSchool : "auto"}`;
  if (!force && teacherInstitutionalState.status === "ready" && teacherInstitutionalState.profile?.id === getPlatformSession().userId && (!teacherInstitutionalState.requestKey || teacherInstitutionalState.requestKey === requestKey) && (!requestedSchool || teacherInstitutionalState.profile?.schoolId === requestedSchool)) return teacherInstitutionalState;
  if (!force && teacherInstitutionalState.promise && teacherInstitutionalState.requestKey === requestKey) return teacherInstitutionalState.promise;
  const revision = teacherInstitutionalState.revision = (teacherInstitutionalState.revision || 0) + 1;
  teacherInstitutionalState.requestKey = requestKey;
  const current = () => teacherInstitutionalState.revision === revision && actor === getTeacherAttendanceActor() && requestKey === `${getTeacherAttendanceActor()}:${getPrintableParams().has("school") ? (getPrintableParams().get("school") || "") : "auto"}`;
  const nextState = { schools: [], profile: null, classes: [], memberships: [], teacherByClass: {}, studentsByClass: {}, studentsById: {}, teacher: null, schoolMembership: null };
  const finish = () => { if (current()) Object.assign(teacherInstitutionalState, nextState); return teacherInstitutionalState; };
  teacherInstitutionalState.status = "loading";
  teacherInstitutionalState.error = "";
  teacherInstitutionalState.promise = (async () => {
    try {
      const client = createSupabaseRestClient();
      const context = await client.getContext({ requireAuthenticated: true, allowedRoles: teacherAllowedRoles });
      const profileRows = await client.request(
        "profiles",
        `?select=id,display_name,platform_role,status&id=${supabaseEq(context.userId)}&limit=1`,
        { requireAuthenticated: true, allowedRoles: teacherAllowedRoles }
      );
      const profile = Array.isArray(profileRows) ? profileRows[0] : null;
      if (!profile?.id || profile.status !== "active") {
        throw new Error("Profile institucional não encontrado para a sessão autenticada.");
      }

      const teacherRows = await client.request(
        "teachers",
        `?select=id,school_id,profile_id,disciplina,status&profile_id=${supabaseEq(profile.id)}&status=eq.active&limit=100`,
        { requireAuthenticated: true, allowedRoles: teacherAllowedRoles }
      );
      const linkedSchoolIds = [...new Set((teacherRows || []).map(item => item.school_id).filter(Boolean))];
      const linkedSchools = linkedSchoolIds.length ? await client.request("schools", `?select=id,nome,status&id=${supabaseIn(linkedSchoolIds)}&status=eq.active`, { requireAuthenticated: true, allowedRoles: teacherAllowedRoles }) : [];
      nextState.schools = linkedSchools || [];
      const selectedSchool = getPrintableParams().has("school") ? requestedSchool : (linkedSchools.length === 1 ? linkedSchools[0].id : "");
      const teacher = (teacherRows || []).find(item => item.school_id === selectedSchool && linkedSchools.some(school => school.id === item.school_id));
      if (!selectedSchool || !teacher) {
        Object.assign(nextState, { status: "empty", profile: { id: profile.id, displayName: profile.display_name || "Professor", role: profile.platform_role, schoolId: "" }, classes: [], memberships: [], teacherByClass: {}, studentsByClass: {}, studentsById: {}, teacher: null, schoolMembership: null });
        return finish();
      }
      if (!teacher?.id || !teacher?.school_id) {
        throw new Error("Não foi possível identificar o vinculo institucional deste professor.");
      }

      const schoolMembershipRows = await client.request(
        "school_memberships",
        `?select=id,school_id,profile_id,membership_role,status&profile_id=${supabaseEq(profile.id)}&school_id=${supabaseEq(teacher.school_id)}&status=eq.active&started_at=lte.${encodeURIComponent(new Date().toISOString())}&or=(ended_at.is.null,ended_at.gt.${encodeURIComponent(new Date().toISOString())})&limit=1`,
        { requireAuthenticated: true, allowedRoles: teacherAllowedRoles }
      );
      const schoolMembership = Array.isArray(schoolMembershipRows) ? schoolMembershipRows[0] : null;
      if (!schoolMembership?.id) {
        throw new Error("School membership ativo não encontrado para este professor.");
      }

      const membershipRows = await client.request(
        "class_teacher_memberships",
        `?select=id,class_id,teacher_id,role,status&teacher_id=${supabaseEq(teacher.id)}&status=eq.active&started_at=lte.${encodeURIComponent(new Date().toISOString())}&or=(ended_at.is.null,ended_at.gt.${encodeURIComponent(new Date().toISOString())})`,
        { requireAuthenticated: true, allowedRoles: teacherAllowedRoles }
      );
      const teacherByClass = Object.fromEntries((membershipRows || []).filter((item) => item.class_id && item.teacher_id).map((item) => [item.class_id, item.teacher_id]));
      const teacherId = teacher.id;
      const classIds = [...new Set((membershipRows || []).map((item) => item.class_id).filter(Boolean))];
      if (!classIds.length) {
        nextState.profile = {
          id: profile.id,
          displayName: profile.display_name || "Professor",
          role: profile.platform_role || context.role,
          teacherId,
          schoolId: teacher.school_id,
        };
        nextState.teacher = teacher;
        nextState.schoolMembership = schoolMembership;
        nextState.classes = [];
        nextState.memberships = membershipRows || [];
        nextState.teacherByClass = teacherByClass;
        nextState.studentsByClass = {};
        nextState.studentsById = {};
        nextState.status = "empty";
        return finish();
      }

      const classRows = await client.request(
        "classes",
        `?select=id,nome,school_id,status,turno,school_year&id=${supabaseIn(classIds)}&school_id=${supabaseEq(teacher.school_id)}&status=eq.active`,
        { requireAuthenticated: true, allowedRoles: teacherAllowedRoles }
      );
      const schoolIds = [...new Set((classRows || []).map((item) => item.school_id).filter(Boolean))];
      const schoolRows = schoolIds.length
        ? await client.request("schools", `?select=id,nome,status&id=${supabaseIn(schoolIds)}`, {
            requireAuthenticated: true,
            allowedRoles: teacherAllowedRoles,
          })
        : [];
      const enrollmentRows = await client.request(
        "enrollments",
        `?select=id,student_id,class_id,school_id,status,students(id,nome,school_id,class_id,status)&status=eq.active&class_id=${supabaseIn(classIds)}&school_id=${supabaseEq(teacher.school_id)}`,
        { requireAuthenticated: true, allowedRoles: teacherAllowedRoles }
      );
      const schoolById = new Map((schoolRows || []).map((item) => [item.id, item]));
      const rawClassById = new Map((classRows || []).map((item) => [item.id, item]));
      const studentsByClass = {};
      const studentsById = {};
      (enrollmentRows || []).forEach((enrollment) => {
        const rawStudent = enrollment.students || {};
        if (!rawStudent.id) return;
        const rawClass = rawClassById.get(enrollment.class_id) || { id: enrollment.class_id };
        const student = {
          ...mapInstitutionalStudent({ ...rawStudent, class_id: enrollment.class_id, school_id: enrollment.school_id }, rawClass),
          enrollmentId: enrollment.id || "",
          enrollmentStatus: normalizeInstitutionalStatus(enrollment.status),
        };
        studentsByClass[enrollment.class_id] = studentsByClass[enrollment.class_id] || [];
        studentsByClass[enrollment.class_id].push(student);
        studentsById[student.id] = student;
      });
      Object.values(studentsByClass).forEach((students) => students.sort((a, b) => a.name.localeCompare(b.name, "pt-BR")));
      const classes = (classRows || [])
        .map((classItem) => ({
          ...mapInstitutionalClass(classItem, schoolById.get(classItem.school_id), studentsByClass[classItem.id]?.length || 0),
          teacherId: teacherByClass[classItem.id] || teacherId,
          membershipRole: (membershipRows || []).find((item) => item.class_id === classItem.id)?.role || "professor",
        }))
        .sort((a, b) => a.name.localeCompare(b.name, "pt-BR"));

      nextState.profile = {
        id: profile.id,
        displayName: profile.display_name || "Professor",
        role: profile.platform_role || context.role,
        teacherId,
        schoolId: teacher.school_id,
      };
      nextState.teacher = teacher;
      nextState.schoolMembership = schoolMembership;
      nextState.classes = classes;
      nextState.memberships = membershipRows || [];
      nextState.teacherByClass = teacherByClass;
      nextState.studentsByClass = studentsByClass;
      nextState.studentsById = studentsById;
      nextState.loadedAt = new Date().toISOString();
      nextState.status = classes.length ? "ready" : "empty";
      return finish();
    } catch (error) {
      nextState.status = "error";
      nextState.error = error.message || "Falha ao carregar dados institucionais.";
      nextState.classes = [];
      nextState.memberships = [];
      nextState.teacherByClass = {};
      nextState.studentsByClass = {};
      nextState.studentsById = {};
      nextState.teacher = null;
      nextState.schoolMembership = null;
      return finish();
    } finally {
      if (revision === teacherInstitutionalState.revision) teacherInstitutionalState.promise = null;
    }
  })();
  return teacherInstitutionalState.promise;
};

const secretariaAllowedRoles = ["secretaria", "admin", "gestor", "coordenador"];
const secretariaViews = ["painel", "alunos", "novoAluno", "turmas", "novaTurma", "professores", "novoProfessor", "matriculas", "responsaveis", "novoResponsavel", "documentos", "pendencias", "frequencia", "diario", "calendario", "avalia", "analytics", "relatorios", "comunicados", "conteudosDisponiveis", "acessosAlunos", "acesso"];
const secretariaOfficialViews = ["painel", "alunos", "matriculas", "acessosAlunos", "responsaveis", "turmas", "professores", "frequencia", "calendario", "avalia", "analytics", "relatorios", "documentos", "comunicados", "conteudosDisponiveis", "acesso"];
const secretariaActiveStatuses = new Set(["active", "ativo"]);
const secretariaSchoolContextStorageKey = "raizes.secretaria.selectedSchoolId";

const isSecretariaActiveStatus = (status) => secretariaActiveStatuses.has(String(status || "active").toLowerCase());
const secretariaStatusLabel = (status) => normalizeInstitutionalStatus(status || "active");
const secretariaAccessLabel = (status) => String(status || "").toLowerCase() === "active" ? "Acesso configurado" : "Acesso não configurado";
const secretariaBadgeTone = (status) => {
  const value = String(status || "").toLowerCase();
  if (["active", "ativo", "published", "received", "present"].includes(value)) return "success";
  if (["pending", "draft", "justified", "not_configured"].includes(value)) return "warning";
  if (["absent", "cancelled"].includes(value)) return "danger";
  if (["transferred", "ended", "archived", "waived"].includes(value)) return "neutral";
  return "info";
};
const secretariaBadge = (label, tone = "neutral") => `<span class="secretaria-badge is-${tone}">${htmlEscape(label)}</span>`;
const secretariaSchoolYear = (enrollment = {}, classItem = {}) => enrollment.school_year || classItem.school_year || classItem.ano_escolar || "Ano nao informado";
const secretariaTodayIso = () => new Date().toISOString().slice(0, 10);
const getSecretariaParams = () => new URLSearchParams(window.location.search);
const getSecretariaCurrentView = () => {
  const view = getSecretariaParams().get("view") || "painel";
  return secretariaViews.includes(view) ? view : "painel";
};

const getSecretariaSchoolStorageKey = () => {
  const actor = getPlatformSession().userId;
  return actor ? `${secretariaSchoolContextStorageKey}:v2:${encodeURIComponent(actor)}` : "";
};

const getStoredSecretariaSchoolId = () => {
  const key = getSecretariaSchoolStorageKey();
  if (!key) return "";
  try {
    return window.localStorage?.getItem(key) || "";
  } catch {
    return "";
  }
};

const setStoredSecretariaSchoolId = (schoolId = "") => {
  const key = getSecretariaSchoolStorageKey();
  if (!key) return;
  try {
    if (schoolId) window.localStorage?.setItem(key, schoolId);
    else window.localStorage?.removeItem(key);
  } catch {}
};

const getRequestedSecretariaSchoolId = () => getSecretariaParams().has("school") ? (getSecretariaParams().get("school") || "") : getStoredSecretariaSchoolId();

const resolveSecretariaSelectedSchool = (schools = []) => {
  if (!getPlatformSession().userId) return {};
  const activeSchools = [...new Map((schools || []).filter(school => school.id && isSecretariaActiveStatus(school.status)).map(school => [school.id, school])).values()];
  const requested = activeSchools.find(school => school.id === getRequestedSecretariaSchoolId());
  // An explicit invalid URL must not silently switch the user's school.
  if (getSecretariaParams().has("school")) return requested || {};
  return requested || (activeSchools.length === 1 ? activeSchools[0] : {});
};

const normalizeSecretariaSchoolScopedData = (payload = {}, selectedSchoolId = "") => {
  if (!selectedSchoolId) return Object.fromEntries(Object.entries(payload).map(([key, value]) => [key, Array.isArray(value) ? [] : value]));
  const selectedSchools = (payload.schools || []).filter((school) => !selectedSchoolId || school.id === selectedSchoolId);
  const selectedClassIds = new Set((payload.classes || []).filter((item) => !selectedSchoolId || item.school_id === selectedSchoolId).map((item) => item.id));
  const selectedStudentIds = new Set((payload.students || []).filter((item) => !selectedSchoolId || item.school_id === selectedSchoolId || selectedClassIds.has(item.class_id)).map((item) => item.id));
  const selectedTeacherIds = new Set((payload.teachers || []).filter((item) => !selectedSchoolId || item.school_id === selectedSchoolId).map((item) => item.id));
  const selectedGuardianIds = new Set();
  const selectedProfileIds = new Set();
  const guardianLinks = (payload.guardianLinks || []).filter((item) => selectedStudentIds.has(item.student_id));
  guardianLinks.forEach((link) => {
    if (link.guardian_id) selectedGuardianIds.add(link.guardian_id);
  });
  const guardians = (payload.guardians || []).filter((item) => selectedStudentIds.has(item.student_id) || (!selectedSchoolId || item.school_id === selectedSchoolId));
  guardians.forEach((guardian) => {
    if (guardian.profile_id) selectedProfileIds.add(guardian.profile_id);
  });
  const institutionalGuardians = (payload.institutionalGuardians || []).filter((item) => selectedGuardianIds.has(item.id) || (!selectedSchoolId || item.school_id === selectedSchoolId));
  institutionalGuardians.forEach((guardian) => {
    if (guardian.profile_id) selectedProfileIds.add(guardian.profile_id);
  });
  (payload.teachers || []).forEach((teacher) => {
    if (selectedTeacherIds.has(teacher.id) && teacher.profile_id) selectedProfileIds.add(teacher.profile_id);
  });
  return {
    schools: selectedSchools,
    profiles: payload.profiles || [],
    teachers: (payload.teachers || []).filter((item) => selectedTeacherIds.has(item.id)),
    classes: (payload.classes || []).filter((item) => selectedClassIds.has(item.id)),
    students: (payload.students || []).filter((item) => selectedStudentIds.has(item.id)),
    enrollments: (payload.enrollments || []).filter((item) => (!selectedSchoolId || item.school_id === selectedSchoolId) || selectedStudentIds.has(item.student_id) || selectedClassIds.has(item.class_id)),
    enrollmentMovements: (payload.enrollmentMovements || []).filter((item) => selectedStudentIds.has(item.student_id) || selectedClassIds.has(item.from_class_id) || selectedClassIds.has(item.to_class_id)),
    guardians,
    institutionalGuardians,
    guardianLinks,
    classTeacherMemberships: (payload.classTeacherMemberships || []).filter((item) => selectedClassIds.has(item.class_id) || selectedTeacherIds.has(item.teacher_id)),
    teacherClassMovements: (payload.teacherClassMovements || []).filter((item) => (!selectedSchoolId || item.school_id === selectedSchoolId) || selectedClassIds.has(item.class_id) || selectedTeacherIds.has(item.teacher_id)),
    schoolMemberships: (payload.schoolMemberships || []).filter((item) => !selectedSchoolId || item.school_id === selectedSchoolId),
    documentTypes: (payload.documentTypes || []).filter((item) => !item.school_id || !selectedSchoolId || item.school_id === selectedSchoolId),
    studentDocuments: (payload.studentDocuments || []).filter((item) => selectedStudentIds.has(item.student_id)),
    studentDocumentEvents: (payload.studentDocumentEvents || []).filter((item) => selectedStudentIds.has(item.student_id)),
    attendanceRecords: (payload.attendanceRecords || []).filter((item) => item.school_id === selectedSchoolId && selectedClassIds.has(item.class_id)),
    attendanceEvents: (payload.attendanceEvents || []).filter((item) => {
      if (!item.attendance_record_id) return false;
      return (payload.attendanceRecords || []).some((record) => record.id === item.attendance_record_id && record.school_id === selectedSchoolId && item.school_id === selectedSchoolId && selectedClassIds.has(record.class_id));
    }),
    classDiaryEntries: (payload.classDiaryEntries || []).filter((item) => item.school_id === selectedSchoolId && selectedClassIds.has(item.class_id)),
    communications: (payload.communications || []).filter((item) => !selectedSchoolId || item.school_id === selectedSchoolId),
    communicationEvents: (payload.communicationEvents || []).filter((item) => (payload.communications || []).some((communication) => communication.id === item.communication_id && (!selectedSchoolId || communication.school_id === selectedSchoolId))),
    communicationDeliverySummaries: (payload.communicationDeliverySummaries || []).filter((item) => (payload.communications || []).some((communication) => communication.id === item.communication_id && (!selectedSchoolId || communication.school_id === selectedSchoolId))),
    studentCredentials: (payload.studentCredentials || []).filter((item) => selectedStudentIds.has(item.student_id) || (!selectedSchoolId || item.school_id === selectedSchoolId)),
    academicYears: (payload.academicYears || []).filter((item) => !selectedSchoolId || item.school_id === selectedSchoolId),
    academicTerms: (payload.academicTerms || []).filter((item) => (payload.academicYears || []).some((year) => year.id === item.academic_year_id && (!selectedSchoolId || year.school_id === selectedSchoolId))),
    schoolDays: (payload.schoolDays || []).filter((item) => !selectedSchoolId || item.school_id === selectedSchoolId),
    classSubjects: (payload.classSubjects || []).filter((item) => selectedClassIds.has(item.class_id) || (!selectedSchoolId || item.school_id === selectedSchoolId)),
    classScheduleSlots: (payload.classScheduleSlots || []).filter((item) => selectedClassIds.has(item.class_id) || (!selectedSchoolId || item.school_id === selectedSchoolId)),
    academicImportBatches: (payload.academicImportBatches || []).filter((item) => !selectedSchoolId || item.school_id === selectedSchoolId),
    academicImportRows: (payload.academicImportRows || []).filter((item) => (payload.academicImportBatches || []).some((batch) => batch.id === item.batch_id && (!selectedSchoolId || batch.school_id === selectedSchoolId))),
  };
};

const getSecretariaDiaryPeriodRange = () => {
  const defaults = getDiaryPeriodDefaultRange();
  const params = getSecretariaParams();
  return {
    from: params.get("diaryFrom") || defaults.from,
    to: params.get("diaryTo") || defaults.to,
  };
};

const getSecretariaAnalyticsPeriodRange = () => {
  const defaults = getDiaryPeriodDefaultRange();
  const params = getSecretariaParams();
  return {
    from: params.get("analyticsFrom") || defaults.from,
    to: params.get("analyticsTo") || defaults.to,
  };
};

const getSecretariaDiaryPeriodKey = (classId, from, to) => `${getTeacherAttendanceActor()}:${secretariaInstitutionalState.selectedSchoolId || ""}:${getDiaryPeriodKey(classId, from, to)}`;
const secretariaDiaryContextAllowed = (classId) => secretariaInstitutionalState.status === "ready" && secretariaInstitutionalState.context?.userId === getPlatformSession().userId &&
  secretariaInstitutionalState.selectedSchoolId === getRequestedSecretariaSchoolId() && (secretariaInstitutionalState.classes || []).some(item => item.id === classId && item.school_id === secretariaInstitutionalState.selectedSchoolId);

const ensureSecretariaDiaryPeriodSummary = async ({ force = false, classId = "", from = "", to = "" } = {}) => {
  const selectedClassId = classId || getSecretariaParams().get("class") || "";
  const range = { ...getSecretariaDiaryPeriodRange(), from: from || getSecretariaDiaryPeriodRange().from, to: to || getSecretariaDiaryPeriodRange().to };
  const key = getSecretariaDiaryPeriodKey(selectedClassId, range.from, range.to);
  if (!selectedClassId || !range.from || !range.to || !secretariaDiaryContextAllowed(selectedClassId)) return secretariaDiaryPeriodState;
  if (!force && secretariaDiaryPeriodState.status === "ready" && secretariaDiaryPeriodState.key === key) return secretariaDiaryPeriodState;
  if (secretariaDiaryPeriodState.promise && secretariaDiaryPeriodState.key === key) return secretariaDiaryPeriodState.promise;
  const revision = secretariaDiaryPeriodState.revision = (secretariaDiaryPeriodState.revision || 0) + 1;
  const current = () => revision === secretariaDiaryPeriodState.revision && key === getSecretariaDiaryPeriodKey(selectedClassId, range.from, range.to) && secretariaDiaryContextAllowed(selectedClassId);
  secretariaDiaryPeriodState.summary = null;
  secretariaDiaryPeriodState.status = "loading";
  secretariaDiaryPeriodState.error = "";
  secretariaDiaryPeriodState.key = key;
  secretariaDiaryPeriodState.promise = (async () => {
    try {
      const client = createSupabaseRestClient();
      const result = await client.request("rpc/secretaria_get_class_diary_period_summary", "", {
        method: "POST",
        body: JSON.stringify({
          p_class_id: selectedClassId,
          p_from: range.from,
          p_to: range.to,
        }),
        requireAuthenticated: true,
        allowedRoles: secretariaAllowedRoles,
      });
      if (!current()) return secretariaDiaryPeriodState;
      const summary = normalizeRpcJson(result);
      if (summary.error) throw new Error(summary.error);
      secretariaDiaryPeriodState.summary = summary;
      secretariaDiaryPeriodState.status = "ready";
    } catch (error) {
      if (!current()) return secretariaDiaryPeriodState;
      secretariaDiaryPeriodState.summary = null;
      secretariaDiaryPeriodState.error = error.message || "Não foi possível consolidar o período do Diário.";
      secretariaDiaryPeriodState.status = "error";
    } finally {
      if (revision === secretariaDiaryPeriodState.revision) secretariaDiaryPeriodState.promise = null;
    }
    return secretariaDiaryPeriodState;
  })();
  return secretariaDiaryPeriodState.promise;
};

const getSecretariaPrimarySchool = () =>
  (secretariaInstitutionalState.schools || []).find((item) => item.id === secretariaInstitutionalState.selectedSchoolId)
  || {};

const getSecretariaCurrentSchoolYear = (school = getSecretariaPrimarySchool()) => {
  const schoolId = school?.id || secretariaInstitutionalState.selectedSchoolId || "";
  const scoped = rows => rows.filter(item => item.school_id === schoolId && /^(19|20|21)\d{2}$/.test(String(item.school_year || "").trim()));
  const academic = scoped(secretariaInstitutionalState.academicYears || []);
  const operational = scoped([...(secretariaInstitutionalState.classes || []), ...(secretariaInstitutionalState.enrollments || [])]);
  const selected = getSecretariaParams().get('year') || '';
  if ([...academic, ...operational].some(item => String(item.school_year) === selected)) return selected;
  // Prefer an explicitly current academic interval, never simply the largest registered year.
  const today = secretariaTodayIso();
  const current = [...new Set(academic.filter(item => item.status === 'active' && item.start_date <= today && item.end_date >= today).map(item => String(item.school_year)))];
  if (current.length === 1) return current[0];
  if (current.length > 1) return '';
  const years = [...new Set(operational.filter(item => isSecretariaActiveStatus(item.status) && (!item.ended_at || item.ended_at > new Date().toISOString())).map(item => String(item.school_year)))];
  const calendarYear = today.slice(0, 4);
  if (years.includes(calendarYear)) return calendarYear;
  return years.length === 1 ? years[0] : '';
};

