const questionBankFallbackStore = {
  questions: demoQuestionBankItems.map((item) => ({ ...item })),
  assessments: savedAssessmentDemo.map((assessment, index) => ({
    id: `demo-assessment-${index + 1}`,
    ...assessment,
    title: assessment.title,
    description: "Avaliação demonstrativa local.",
    component: index === 0 ? "Lingua Portuguesa" : "Matematica",
    year: index === 0 ? "2o ano" : "5o ano",
    instructions: "Leia com atencao e marque apenas uma alternativa por questao.",
    questions: [],
  })),
};

// Only explicit ENEM metadata from the known catalog shape; never infer from text,
// school year, component, the resolver boolean, or an absent foreign-language option.
// Segment filtering uses explicit stage data only; ENEM origin/year grants no stage.
const questionBankStageFilterValue = (value) => {
  const stage = String(value ?? '').trim();
  const key = stage.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().replace(/[\s-]+/g, '_');
  return key === 'ENSINO_MEDIO' ? 'ENSINO_MEDIO' : stage;
};
const questionBankFilterValue = (item, key) => key === 'stage'
  ? questionBankStageFilterValue(item.stage) : String(item[key] ?? '');

const questionBankExamMetadata = (row) => {
  const exam = row.metadata?.enem;
  if (!exam || typeof exam !== 'object' || Array.isArray(exam)) return {examYear:'', language:'', theme:''};
  const year = String(exam.examYear ?? '').trim();
  const languages = {'português':'Português', 'portugues':'Português', 'pt':'Português', 'pt-br':'Português', 'inglês':'Inglês', 'ingles':'Inglês', 'en':'Inglês', 'en-us':'Inglês', 'espanhol':'Espanhol', 'es':'Espanhol'};
  const languageKey = String(exam.language ?? '').trim().toLowerCase();
  return {examYear: /^\d{4}$/.test(year) ? year : '', language: Object.hasOwn(languages, languageKey) ? languages[languageKey] : '', theme: typeof exam.theme === 'string' ? exam.theme.trim() : ''};
};
const mapQuestionFromSupabase = (row) => {
  const alternatives = [...(row.alternatives || [])].sort((a, b) => (a.position || 0) - (b.position || 0));
  const correctIndex = alternatives.findIndex((alternative) => alternative.is_correct);
  const metadata = row.metadata || {};
  const provenance = row.provenance || {};
  return {
    id: row.code,
    uuid: row.id,
    title: row.internal_title,
    component: row.component,
    stage: row.stage,
    year: row.school_year,
    ...questionBankExamMetadata(row),
    unit: row.thematic_unit || "",
    object: row.knowledge_object || "",
    skill: row.bncc_skill || "",
    descriptor: row.reference_matrix || row.curriculum_matrix || "",
    curriculumMatrix: row.curriculum_matrix || row.reference_matrix || "",
    curriculumSource: row.curriculum_source || "BNCC",
    proficiency: row.proficiency_level || "",
    difficulty: row.difficulty || "",
    cognitiveProcess: row.cognitive_process || "",
    type: row.question_type,
    resource: row.media?.[0]?.media_type || (row.base_text ? "Texto-base" : "Texto-base"),
    estimatedTime: row.estimated_minutes || 0,
    accessibility: row.accessibility_notes || "",
    originType: row.origin_type || metadata.origin || row.source?.source_type || "GLOBAL_RAIZES",
    ownershipScope: row.ownership_scope || "GLOBAL_RAIZES",
    ownerUserId: row.owner_user_id || row.author_user_id || "",
    sourceQuestionId: row.source_question_id || provenance.source_question_id || metadata.source_question_id || "",
    sourceQuestionCode: provenance.source_question_code || metadata.source_question_code || "",
    adaptedAt: row.adapted_at || "",
    legalClassification: row.legal_classification,
    sourceId: row.source_id,
    sourceName: row.source?.name || "Conteúdo autoral Raízes e Saberes",
    author: row.author_name,
    license: row.license?.name || row.source?.license?.name || "Uso interno demonstrativo Raízes e Saberes",
    legalStatus: row.source?.legal_status || "",
    createdAt: row.created_at,
    reviewedAt: row.last_reviewed_at || row.updated_at || row.created_at,
    version: row.version,
    reviewer: row.reviewer_name || "Revisão pendente",
    curationStatus: row.curation_status,
    publicationStatus: row.publication_status,
    workflowStatus: row.workflow_status || (row.publication_status === "PUBLICADO" ? "APROVADO" : "EM_ELABORACAO"),
    workflowVersion: row.workflow_version || 1,
    statement: row.statement,
    commandText: row.command_text || row.statement,
    baseText: row.base_text || "",
    alternatives: alternatives.map((alternative) => alternative.body),
    alternativeRows: alternatives,
    correctAlternative: correctIndex >= 0 ? correctIndex : 0,
    justification: row.justification || "",
    pedagogicalComment: row.pedagogical_comment || row.justification || "",
    distractors: alternatives.flatMap((alternative) => (alternative.distractor || []).map((entry) => entry.analysis)),
    rightFeedback: row.success_feedback || "",
    wrongFeedback: row.error_feedback || "",
    intervention: row.recommended_intervention || "",
    usedCount: row.usage_count || 0,
    lastUsedClass: row.last_used_class || "",
    authorizedRichContent: row.authorizedRichContent,
    raw: row,
  };
};

const mapAssessmentFromSupabase = (row) => ({
  id: row.id,
  title: row.title,
  status: row.status,
  isAssigned: Array.isArray(row.assignments) && row.assignments.length > 0,
  items: row.questions?.length || row.question_count || 0,
  className: row.class_name || "Sem turma",
  date: row.application_date || "Sem data",
  description: row.description || "",
  component: row.component || "",
  year: row.school_year || "",
  instructions: row.instructions || "",
  questions: [...(row.questions || [])].sort((a, b) => a.position - b.position),
  booklets: [...(row.booklets || [])].sort((a, b) => a.position - b.position),
  skillMap: row.skill_map || [],
  maxBooklets: row.max_booklets || 1,
  matrix: row.matrix || "",
  raw: row,
});

const questionBankDataService = (() => {
  const client = () => createSupabaseRestClient();
  const questionSelect =
    "*,source:question_sources(*,license:question_licenses(*)),license:question_licenses(*),alternatives:question_alternatives(*,distractor:question_distractor_analyses(*)),media:question_media(*)";
  const assessmentSelect =
    "*,assignments:assessment_assignments!assessment_assignments_assessment_id_fkey(id),questions:assessment_questions(*,question:question_items(code,internal_title,estimated_minutes,publication_status,curation_status,workflow_status,workflow_version,bncc_skill,reference_matrix,curriculum_matrix)),booklets:assessment_booklets(*,questions:assessment_booklet_questions(*))";
  const teacherResolverRoles = new Set(["professor", "teacher"]);
  let questionAccessState = { status: "UNLOADED", total: null, detailsTotal: null, source: "" };
  const isTeacherResolverContext = (context = {}) => Boolean(context.userId && teacherResolverRoles.has(context.role));
  const normalizeQuestionBankText = (value = "") =>
    String(value)
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .toLowerCase();
  const getTeacherResolverContext = async (request, context = {}) => {
    const teacherRows = await request(
      "teachers",
      `?select=id,school_id,profile_id,status,full_name&profile_id=${supabaseEq(context.userId)}&status=eq.active&limit=1`,
      { requireAuthenticated: true, allowedRoles: allowedAssessmentRoles }
    );
    const teacher = Array.isArray(teacherRows) ? teacherRows[0] : null;
    if (!teacher?.id || !teacher?.school_id) {
      throw new Error("CONTENT_RESOLVER_TEACHER_CONTEXT_NOT_FOUND");
    }
    const memberships = await request("class_teacher_memberships",
      `?select=class_id,status,ended_at&teacher_id=${supabaseEq(teacher.id)}&status=eq.active`,
      { requireAuthenticated: true, allowedRoles: allowedAssessmentRoles });
    const classIds = [...new Set((Array.isArray(memberships) ? memberships : [])
      .filter(row => row.status === "active" && (!row.ended_at || Date.parse(row.ended_at) > Date.now()))
      .map(row => row.class_id).filter(Boolean))];
    return { content_type: "QUESTION", school_id: teacher.school_id, limit: 10, classIds };
  };
  let teacherQuestionLoadGeneration = 0;
  const getTeacherResolvedQuestionRows = async (request, context = {}) => {
    const generation = ++teacherQuestionLoadGeneration;
    const assertCurrent = () => {
      if (!context.userId || getSupabaseUserContext().userId !== context.userId) throw new Error("CONTENT_RESOLVER_ACCOUNT_CHANGED");
      if (generation !== teacherQuestionLoadGeneration) throw new Error("CONTENT_RESOLVER_STALE_LOAD");
    };
    const checkedRequest = async (resource, query, options) => {
      assertCurrent();
      const value = await request(resource, query, { ...options, expectedUserId: context.userId });
      assertCurrent();
      return value;
    };
    const { classIds, ...resolverContext } = await getTeacherResolverContext(checkedRequest, context);
    const rows = new Map();
    let result = { status: "PASS", total: 0, details_total: 0 };
    // Keep explicit class scope for BOTH legacy and dynamic resolvers. Legacy
    // treats a missing class as an unrestricted grade; never issue that request.
    for (const classId of classIds) {
      let offset = 0;
      do {
        result = normalizeRpcJson(await checkedRequest("rpc/content_resolve_question_details_for_user", "", {
          method: "POST", requireAuthenticated: true, allowedRoles: allowedAssessmentRoles,
          body: JSON.stringify({ p_context: { ...resolverContext, class_id: classId, offset } }),
        }));
        if (result?.status === "FEATURE_DISABLED") return { enabled: false, result, rows: [] };
        if (result?.status !== "PASS") throw new Error(`CONTENT_RESOLVER_${result?.status || "FAILED"}`);
        const total = Number(result.total);
        if (!Number.isSafeInteger(total) || total < 0) throw new Error("CONTENT_RESOLVER_INVALID_TOTAL");
        // Validate each authorized response before merging it into the acervo.
        // The 4 MiB response budget applies to this page, not all pages combined.
        if (!Array.isArray(result.items) || result.items.length > resolverContext.limit) throw new Error("CONTENT_RESOLVER_INVALID_PAGE");
        if (result.items.length === 0 && offset < total) throw new Error("CONTENT_RESOLVER_INCOMPLETE_PAGE");
        const page = await enrichTeacherRows(result.items, {
          request: (resource, query) => checkedRequest(resource, query, { requireAuthenticated: true, allowedRoles: allowedAssessmentRoles }),
          current: () => { assertCurrent(); return true; },
          validateContent: qbValidateTeacherRich,
        });
        assertCurrent();
        for (const row of page) rows.set(row.id, row);
        // Advance by received rows so a shorter server page cannot skip items.
        offset += result.items.length;
        if (offset >= total) break;
      } while (true);
    }
    assertCurrent();
    return { enabled: true, result: { ...result, total: rows.size, details_total: rows.size }, rows: [...rows.values()] };
  };
  const pickDefaultQuestionSource = (sources = []) => {
    const validSources = sources.filter((source) => source?.id && (source.license_id || source.license?.id));
    return (
      validSources.find((source) => normalizeQuestionBankText(source.name).includes("raizes e saberes") && normalizeQuestionBankText(source.name).includes("banco demonstrativo")) ||
      validSources.find((source) => normalizeQuestionBankText(source.institution_name || source.author_name || source.name).includes("raizes e saberes")) ||
      validSources.find((source) => ["HOMOLOGADO", "APROVADO"].includes(String(source.curation_status || "").toUpperCase())) ||
      validSources[0] ||
      null
    );
  };
  const pickDefaultQuestionLicense = (licenses = [], source = null) => {
    const sourceLicenseId = source?.license_id || source?.license?.id || "";
    if (sourceLicenseId) return licenses.find((license) => license.id === sourceLicenseId) || source?.license || { id: sourceLicenseId };
    return (
      licenses.find((license) => normalizeQuestionBankText(license.name).includes("raizes e saberes")) ||
      licenses.find((license) => license.publication_allowed) ||
      licenses[0] ||
      null
    );
  };
  const buildQuestionProvenancePayload = (payload, source, license) => {
    const sourceId = payload.source_id || source?.id || "";
    const licenseId = payload.license_id || source?.license_id || source?.license?.id || license?.id || "";
    if (!sourceId || !licenseId) {
      throw new Error("QUESTION_PROVENANCE_NOT_CONFIGURED");
    }
    return {
      ...payload,
      source_id: sourceId,
      license_id: licenseId,
      legal_classification: payload.legal_classification || "ITEM_AUTORAL_RAIZES_SABERES_ALINHADO_SAEB",
      metadata: {
        ...(payload.metadata || {}),
        provenance_resolved_by: payload.source_id && payload.license_id ? "question_bank_payload" : "question_bank_editorial_ui",
        source_name: source?.name || payload.metadata?.source_name || "",
        license_name: license?.name || source?.license?.name || payload.metadata?.license_name || "",
      },
    };
  };

  const fallback = {
    async listQuestions() {
      return questionBankFallbackStore.questions;
    },
    async getQuestionById(id) {
      return questionBankFallbackStore.questions.find((item) => item.id === id || item.uuid === id);
    },
    async listAlternatives(questionId) {
      return (await this.getQuestionById(questionId))?.alternatives || [];
    },
    async listSources() {
      return questionSourcesDemo;
    },
    async listLicenses() {
      return [{ id: "demo-license", name: "Uso interno demonstrativo Raízes e Saberes" }];
    },
    async listAssessments() {
      return questionBankFallbackStore.assessments;
    },
    async getAssessmentById(id) {
      return questionBankFallbackStore.assessments.find((assessment) => assessment.id === id);
    },
    async createAssessment(payload) {
      const assessment = {
        id: `demo-assessment-${Date.now()}`,
        status: "RASCUNHO",
        items: 0,
        className: payload.class_name || "Turma demonstrativa",
        date: payload.application_date || "",
        questions: [],
        ...payload,
        year: payload.school_year,
      };
      questionBankFallbackStore.assessments.unshift(assessment);
      return assessment;
    },
    async createAssessmentFromBank(payload) {
      const assessment = await this.createAssessment(payload.assessment || payload);
      const questions = (payload.questions || [])
        .map((entry, index) => {
          const question = questionBankFallbackStore.questions.find((item) => item.uuid === entry.question_id || item.id === entry.question_id);
          if (!question) return null;
          return {
            id: `${assessment.id}-${entry.question_id}`,
            question_id: question.uuid || question.id,
            position: index + 1,
            points: entry.points || 1,
            question,
          };
        })
        .filter(Boolean);
      assessment.questions = questions;
      assessment.items = questions.length;
      assessment.booklets = [{ code: "A", title: "Caderno A", position: 1, question_count: questions.length }];
      return assessment;
    },
    async replaceAssessmentItems(assessmentId, payload) {
      const assessment = await this.updateAssessment(assessmentId, payload);
      const questions = (payload.questions || [])
        .map((entry, index) => {
          const question = questionBankFallbackStore.questions.find((item) => item.uuid === entry.question_id || item.id === entry.question_id);
          if (!question) return null;
          return {
            id: `${assessment.id}-${entry.question_id}`,
            question_id: question.uuid || question.id,
            position: index + 1,
            points: entry.points || 1,
            question,
          };
        })
        .filter(Boolean);
      assessment.questions = questions;
      assessment.items = questions.length;
      assessment.booklets = [{ code: "A", title: "Caderno A", position: 1, question_count: questions.length }];
      return assessment;
    },
    async updateAssessment(id, payload) {
      const assessment = questionBankFallbackStore.assessments.find((entry) => entry.id === id);
      Object.assign(assessment, payload, { year: payload.school_year || assessment.year });
      return assessment;
    },
    async archiveAssessment(id) {
      return this.updateAssessment(id, { status: "ARQUIVADA", archived_at: new Date().toISOString() });
    },
    async duplicateAssessment(id) {
      const assessment = await this.getAssessmentById(id);
      return this.createAssessment({ ...assessment, title: `${assessment.title} - copia`, duplicated_from_id: id });
    },
    async addQuestionToAssessment(assessmentId, questionId, points = 1) {
      const assessment = await this.getAssessmentById(assessmentId);
      const question = await this.getQuestionById(questionId);
      if (!assessment || !question || question.publicationStatus !== "PUBLICADO") return null;
      assessment.questions.push({ id: `${assessmentId}-${questionId}`, question_id: question.uuid || question.id, position: assessment.questions.length + 1, points, question });
      assessment.items = assessment.questions.length;
      return assessment.questions.at(-1);
    },
    async removeQuestionFromAssessment(assessmentId, questionId) {
      const assessment = await this.getAssessmentById(assessmentId);
      assessment.questions = assessment.questions.filter((entry) => entry.question_id !== questionId && entry.question?.id !== questionId);
      assessment.items = assessment.questions.length;
      return assessment;
    },
    async reorderQuestions(assessmentId, orderedQuestionIds) {
      const assessment = await this.getAssessmentById(assessmentId);
      assessment.questions = orderedQuestionIds
        .map((id, index) => ({ ...assessment.questions.find((entry) => entry.question_id === id || entry.question?.id === id), position: index + 1 }))
        .filter((entry) => entry.question_id || entry.question);
      return assessment.questions;
    },
    async updateQuestionPoints(assessmentId, questionId, points = 1) {
      const assessment = await this.getAssessmentById(assessmentId);
      const entry = assessment?.questions.find((item) => item.question_id === questionId || item.question?.id === questionId || item.question?.uuid === questionId);
      if (entry) entry.points = points;
      return entry || null;
    },
    async registerUsage() {
      return null;
    },
    async getCurationHistory(questionId) {
      return [{ comment: "Histórico local demonstrativo.", question_id: questionId, created_at: new Date().toISOString() }];
    },
    async generatePrintExport(payload) {
      return {
        export: {
          id: `local-qb-export-${Date.now()}`,
          export_type: payload.exportType,
          format: payload.format || "PDF",
          status: "ready",
        },
        payload,
      };
    },
    async createQuestionItem() {
      throw new Error("Criação editorial exige Supabase real e perfil autorizado.");
    },
    async adaptQuestionItem(sourceQuestionId, payload = {}) {
      const source = await this.getQuestionById(sourceQuestionId);
      if (!source) throw new Error("Questão original não encontrada.");
      const adapted = {
        ...source,
        id: `LOCAL-ADAPT-${Date.now().toString().slice(-6)}`,
        uuid: `local-adapt-${Date.now()}`,
        title: payload.internal_title || `${source.title} - adaptação`,
        statement: payload.statement || source.statement,
        commandText: payload.command_text || source.commandText,
        baseText: payload.base_text ?? source.baseText,
        alternatives: (payload.alternatives || []).map((item) => item.body).filter(Boolean).length
          ? payload.alternatives.map((item) => item.body)
          : source.alternatives,
        correctAlternative: Math.max(0, (payload.alternatives || []).findIndex((item) => item.is_correct)),
        justification: payload.justification || source.justification,
        intervention: payload.recommended_intervention || source.intervention,
        originType: "TEACHER_ADAPTATION",
        ownershipScope: "TEACHER_PRIVATE",
        ownerUserId: getSupabaseUserContext().userId || "local-professor",
        sourceQuestionId: source.uuid || source.id,
        sourceQuestionCode: source.id,
      };
      questionBankFallbackStore.questions.unshift(adapted);
      return adapted;
    },
    async updateQuestionItem() {
      throw new Error("Edição editorial exige Supabase real e perfil autorizado.");
    },
    async replaceQuestionAlternatives() {
      throw new Error("Alternativas editoriais exigem Supabase real e perfil autorizado.");
    },
    async setQuestionWorkflow() {
      throw new Error("Workflow editorial exige Supabase real e perfil autorizado.");
    },
  };

  const remote = {
    async listQuestions() {
      const { request, getContext } = client();
      const context = await getContext();
      if (isTeacherResolverContext(context)) {
        const resolved = await getTeacherResolvedQuestionRows(request, context);
        questionAccessState = {
          status: resolved.result?.status || "UNKNOWN",
          total: Number(resolved.result?.total ?? 0),
          detailsTotal: Number(resolved.result?.details_total ?? resolved.rows.length ?? 0),
          source: resolved.result?.detail_source || "content_resolve_question_details_for_user",
        };
        return resolved.rows.map((row) => mapQuestionFromSupabase({
          ...row,
          metadata: {
            ...(row.metadata || {}),
            content_resolver: questionAccessState.source,
            resolver_status: questionAccessState.status,
          },
        }));
      }
      questionAccessState = { status: "EDITORIAL_FULL_BANK", total: null, detailsTotal: null, source: "question_items" };
      const rows = await request("question_items", `?select=${questionSelect}&order=last_reviewed_at.desc.nullslast&order=created_at.desc`);
      return rows.map(mapQuestionFromSupabase);
    },
    async getQuestionById(id) {
      const { request, getContext } = client();
      const context = await getContext();
      if (isTeacherResolverContext(context)) {
        const resolved = await getTeacherResolvedQuestionRows(request, context);
        const mapped = resolved.rows.map(mapQuestionFromSupabase);
        return mapped.find((item) => item.id === id || item.uuid === id) || null;
      }
      const column = String(id).startsWith("RS-") ? "code" : "id";
      const rows = await request("question_items", `?${column}=eq.${encodeURIComponent(id)}&select=${questionSelect}&limit=1`);
      return rows[0] ? mapQuestionFromSupabase(rows[0]) : null;
    },
    async listAlternatives(questionId) {
      const { request } = client();
      return request("question_alternatives", `?question_id=eq.${encodeURIComponent(questionId)}&select=*,distractor:question_distractor_analyses(*)&order=position.asc`);
    },
    async listSources() {
      const { request } = client();
      return request("question_sources", "?select=*,license:question_licenses(*)&order=name.asc");
    },
    async listLicenses() {
      const { request } = client();
      return request("question_licenses", "?select=*&order=name.asc");
    },
    async listAssessments() {
      const { request } = client();
      try {
        const rows = await request("assessments", `?select=${assessmentSelect}&status=neq.ARQUIVADA&order=updated_at.desc`);
        return rows.map(mapAssessmentFromSupabase);
      } catch (error) {
        if (String(error.message || "").includes("Sessao expirada")) {
          return [];
        }
        throw error;
      }
    },
    async getAssessmentById(id, actorOptions={}) {
      const { request } = client();
      const rows = await request("assessments", `?id=eq.${encodeURIComponent(id)}&select=${assessmentSelect}&limit=1`,{requireAuthenticated:true,allowedRoles:allowedAssessmentRoles,expectedUserId:actorOptions.expectedUserId,signal:actorOptions.signal});
      return rows[0] ? mapAssessmentFromSupabase(rows[0]) : null;
    },
    async createAssessment(payload) {
      const { request, getContext } = client();
      const context = await getContext({ requireAuthenticated: true, allowedRoles: allowedAssessmentRoles });
      const [row] = await request("assessments", "", {
        method: "POST",
        requireAuthenticated: true,
        allowedRoles: allowedAssessmentRoles,
        body: JSON.stringify({
          owner_user_id: context.userId,
          owner_role: context.role,
          status: "RASCUNHO",
          ...payload,
        }),
      });
      return mapAssessmentFromSupabase(row);
    },
    async createAssessmentFromBank(payload, actorOptions={}) {
      const { request } = client();
      await resolveSupabaseUserContext({ requireAuthenticated: true, allowedRoles: allowedAssessmentRoles });
      const result = await request("rpc/avalia_plus_create_assessment_from_bank", "", {
        expectedUserId:actorOptions.expectedUserId,signal:actorOptions.signal,
        method: "POST",
        requireAuthenticated: true,
        allowedRoles: allowedAssessmentRoles,
        body: JSON.stringify({ p_payload: payload }),
      });
      return mapAssessmentFromSupabase({
        ...(result.assessment || {}),
        questions: result.questions || [],
        booklets: result.booklets || [],
        skill_map: result.skill_map || [],
      });
    },
    async replaceAssessmentItems(assessmentId, payload, actorOptions={}) {
      const { request } = client();
      await resolveSupabaseUserContext({ requireAuthenticated: true, allowedRoles: allowedAssessmentRoles });
      const result = await request("rpc/avalia_plus_replace_assessment_items", "", {
        expectedUserId:actorOptions.expectedUserId,signal:actorOptions.signal,
        method: "POST",
        requireAuthenticated: true,
        allowedRoles: allowedAssessmentRoles,
        body: JSON.stringify({
          p_assessment_id: assessmentId,
          p_payload: payload,
        }),
      });
      return mapAssessmentFromSupabase({
        ...(result.assessment || {}),
        questions: result.questions || [],
        booklets: result.booklets || [],
        skill_map: result.skill_map || [],
      });
    },
    async updateAssessment(id, payload) {
      const { request } = client();
      const [row] = await request("assessments", `?id=eq.${encodeURIComponent(id)}`, {
        method: "PATCH",
        requireAuthenticated: true,
        allowedRoles: allowedAssessmentRoles,
        body: JSON.stringify({ ...payload, updated_at: new Date().toISOString() }),
      });
      return mapAssessmentFromSupabase(row);
    },
    async archiveAssessment(id) {
      return this.updateAssessment(id, { status: "ARQUIVADA", archived_at: new Date().toISOString() });
    },
    async duplicateAssessment(id) {
      const assessment = await this.getAssessmentById(id);
      const copy = await this.createAssessment({
        title: `${assessment.title} - copia`,
        description: assessment.description,
        component: assessment.component,
        school_year: assessment.year,
        class_name: assessment.className,
        instructions: assessment.instructions,
        application_date: assessment.date === "Sem data" ? null : assessment.date,
        duplicated_from_id: id,
      });
      for (const item of assessment.questions) {
        await this.addQuestionToAssessment(copy.id, item.question_id, item.points);
      }
      return this.getAssessmentById(copy.id);
    },
    async addQuestionToAssessment(assessmentId, questionId, points = 1) {
      await resolveSupabaseUserContext({ requireAuthenticated: true, allowedRoles: allowedAssessmentRoles });
      const assessment = await this.getAssessmentById(assessmentId);
      const question = await this.getQuestionById(questionId);
      const existing = (assessment?.questions || []).map((entry) => ({
        question_id: entry.question_id || entry.question?.id || entry.question?.uuid,
        points: entry.points || 1,
      }));
      if (!existing.some((entry) => entry.question_id === (question.uuid || questionId))) {
        existing.push({ question_id: question.uuid || questionId, points });
      }
      const row = await this.replaceAssessmentItems(assessmentId, {
        title: assessment.title,
        description: assessment.description,
        instructions: assessment.instructions,
        component: assessment.component,
        school_year: assessment.year,
        class_name: assessment.className,
        application_date: assessment.date === "Sem data" ? null : assessment.date,
        questions: existing.map((entry, index) => ({ ...entry, position: index + 1 })),
        booklets: [
          {
            code: "A",
            title: "Caderno A",
            position: 1,
            questions: existing.map((entry, index) => ({ question_id: entry.question_id, position: index + 1 })),
          },
        ],
      });
      await this.registerUsage(question.uuid || questionId, assessmentId, "adicionada_em_avaliacao");
      return row;
    },
    async removeQuestionFromAssessment(assessmentId, questionId) {
      const assessment = await this.getAssessmentById(assessmentId);
      const existing = (assessment?.questions || [])
        .filter((entry) => ![entry.question_id, entry.question?.id, entry.question?.uuid, entry.question?.code].includes(questionId))
        .map((entry) => ({ question_id: entry.question_id || entry.question?.id || entry.question?.uuid, points: entry.points || 1 }))
        .filter((entry) => entry.question_id);
      return this.replaceAssessmentItems(assessmentId, {
        title: assessment.title,
        description: assessment.description,
        instructions: assessment.instructions,
        component: assessment.component,
        school_year: assessment.year,
        class_name: assessment.className,
        application_date: assessment.date === "Sem data" ? null : assessment.date,
        questions: existing.map((entry, index) => ({ ...entry, position: index + 1 })),
        booklets: [
          {
            code: "A",
            title: "Caderno A",
            position: 1,
            questions: existing.map((entry, index) => ({ question_id: entry.question_id, position: index + 1 })),
          },
        ],
      });
    },
    async reorderQuestions(assessmentId, orderedQuestionIds) {
      const assessment = await this.getAssessmentById(assessmentId);
      const byId = new Map((assessment?.questions || []).map((entry) => [entry.question_id || entry.question?.id || entry.question?.uuid || entry.question?.code, entry]));
      const byCode = new Map((assessment?.questions || []).map((entry) => [entry.question?.code, entry]));
      const ordered = orderedQuestionIds
        .map((questionId) => byId.get(questionId) || byCode.get(questionId))
        .filter(Boolean)
        .map((entry) => ({ question_id: entry.question_id || entry.question?.id || entry.question?.uuid, points: entry.points || 1 }))
        .filter((entry) => entry.question_id);
      return this.replaceAssessmentItems(assessmentId, {
        title: assessment.title,
        description: assessment.description,
        instructions: assessment.instructions,
        component: assessment.component,
        school_year: assessment.year,
        class_name: assessment.className,
        application_date: assessment.date === "Sem data" ? null : assessment.date,
        questions: ordered.map((entry, index) => ({ ...entry, position: index + 1 })),
        booklets: [
          {
            code: "A",
            title: "Caderno A",
            position: 1,
            questions: ordered.map((entry, index) => ({ question_id: entry.question_id, position: index + 1 })),
          },
        ],
      });
    },
    async updateQuestionPoints(assessmentId, questionId, points = 1) {
      const assessment = await this.getAssessmentById(assessmentId);
      const existing = (assessment?.questions || [])
        .map((entry) => ({
          question_id: entry.question_id || entry.question?.id || entry.question?.uuid,
          points: [entry.question_id, entry.question?.id, entry.question?.uuid, entry.question?.code].includes(questionId) ? points : entry.points || 1,
        }))
        .filter((entry) => entry.question_id);
      return this.replaceAssessmentItems(assessmentId, {
        title: assessment.title,
        description: assessment.description,
        instructions: assessment.instructions,
        component: assessment.component,
        school_year: assessment.year,
        class_name: assessment.className,
        application_date: assessment.date === "Sem data" ? null : assessment.date,
        questions: existing.map((entry, index) => ({ ...entry, position: index + 1 })),
        booklets: [
          {
            code: "A",
            title: "Caderno A",
            position: 1,
            questions: existing.map((entry, index) => ({ question_id: entry.question_id, position: index + 1 })),
          },
        ],
      });
    },
    async registerUsage(questionId, assessmentId, usageType = "visualizada") {
      const { request, getContext } = client();
      const context = await getContext();
      if (!context.userId || context.role === "anonymous") return null;
      return request("question_usage_logs", "", {
        method: "POST",
        body: JSON.stringify({
          question_id: questionId,
          assessment_id: assessmentId || null,
          user_id: context.userId,
          user_role: context.role,
          usage_type: usageType,
          metadata: { module: "banco-questoes" },
        }),
      });
    },
    async getCurationHistory(questionId) {
      const question = await this.getQuestionById(questionId);
      const { request } = client();
      return request("question_curation_history", `?question_id=eq.${encodeURIComponent(question.uuid || questionId)}&select=*&order=created_at.desc&limit=8`);
    },
    async generatePrintExport({ assessmentId, exportType = "STUDENT_TEST", format = "PDF", classId = null, bookletId = null }) {
      const { request } = client();
      return normalizeRpcJson(await request("rpc/teacher_generate_assessment_print_export", "", {
        method: "POST",
        requireAuthenticated: true,
        allowedRoles: allowedAssessmentRoles,
        body: JSON.stringify({
          p_assessment_id: assessmentId,
          p_export_type: exportType,
          p_format: format,
          p_assignment_id: null,
          p_class_id: classId,
          p_booklet_id: bookletId,
        }),
      }));
    },
    async createQuestionItem(payload) {
      const { request } = client();
      await resolveSupabaseUserContext({ requireAuthenticated: true, allowedRoles: allowedQuestionCreationRoles });
      let itemPayload = payload;
      if (!itemPayload.source_id || !itemPayload.license_id) {
        const [sources, licenses] = await Promise.all([this.listSources(), this.listLicenses()]);
        const source = pickDefaultQuestionSource(sources);
        const license = pickDefaultQuestionLicense(licenses, source);
        itemPayload = buildQuestionProvenancePayload(itemPayload, source, license);
      }
      const row = normalizeRpcJson(await request("rpc/avalia_plus_create_item", "", {
        method: "POST",
        requireAuthenticated: true,
        allowedRoles: allowedQuestionCreationRoles,
        body: JSON.stringify({ p_item: itemPayload }),
      }));
      if (!row.id) throw new Error("Resposta inválida do cadastro de questões. Recarregue antes de tentar novamente.");
      const alternatives = await this.listAlternatives(row.id);
      return mapQuestionFromSupabase({ ...row, alternatives, media: [] });
    },
    async adaptQuestionItem(sourceQuestionId, payload) {
      const { request } = client();
      await resolveSupabaseUserContext({ requireAuthenticated: true, allowedRoles: allowedQuestionAdaptationRoles });
      const row = await request("rpc/avalia_plus_adapt_question", "", {
        method: "POST",
        requireAuthenticated: true,
        allowedRoles: allowedQuestionAdaptationRoles,
        body: JSON.stringify({
          p_source_question_id: sourceQuestionId,
          p_item: payload,
        }),
      });
      const alternatives = await request("question_alternatives", `?question_id=eq.${encodeURIComponent(row.id)}&select=*&order=position.asc`, {
        requireAuthenticated: true,
        allowedRoles: allowedQuestionAdaptationRoles,
      });
      return mapQuestionFromSupabase({ ...row, alternatives, media: [] });
    },
    async updateQuestionItem(questionId, payload, alternatives = null) {
      const { request } = client();
      await resolveSupabaseUserContext({ requireAuthenticated: true, allowedRoles: allowedQuestionEditRoles });
      const row = normalizeRpcJson(await request("rpc/avalia_plus_update_question_item", "", {
        method: "POST",
        requireAuthenticated: true,
        allowedRoles: allowedQuestionEditRoles,
        body: JSON.stringify({
          p_question_id: questionId,
          p_item: payload,
          p_alternatives: alternatives,
        }),
      }));
      if (!row.id) throw new Error("Resposta inválida do cadastro de questões. Recarregue antes de tentar novamente.");
      const nextAlternatives = await this.listAlternatives(row.id);
      return row ? mapQuestionFromSupabase({ ...row, alternatives: nextAlternatives, media: [] }) : null;
    },
    async replaceQuestionAlternatives(questionId, alternatives = []) {
      const { request } = client();
      await resolveSupabaseUserContext({ requireAuthenticated: true, allowedRoles: allowedQuestionEditRoles });
      return request("rpc/avalia_plus_replace_question_alternatives", "", {
        method: "POST",
        requireAuthenticated: true,
        allowedRoles: allowedQuestionEditRoles,
        body: JSON.stringify({
          p_question_id: questionId,
          p_alternatives: alternatives,
        }),
      });
    },
    async setQuestionWorkflow(questionId, status, comment = "") {
      const { request } = client();
      await resolveSupabaseUserContext({ requireAuthenticated: true, allowedRoles: allowedQuestionEditRoles });
      const row = normalizeRpcJson(await request("rpc/avalia_plus_set_item_workflow", "", {
        method: "POST",
        requireAuthenticated: true,
        allowedRoles: allowedQuestionEditRoles,
        body: JSON.stringify({
          p_question_id: questionId,
          p_status: status,
          p_comment: comment,
        }),
      }));
      if (!row.id) throw new Error("Resposta inválida do cadastro de questões. Recarregue antes de tentar novamente.");
      return mapQuestionFromSupabase({ ...row, alternatives: [], media: [] });
    },
  };

  const productionMissingConfig = {
    async listQuestions() {
      throw new Error("Banco de Questões sem conexão Supabase em ambiente de produção. Configure supabase-config.js com URL e anon key pública.");
    },
  };
  const active = () => {
    const currentClient = client();
    if (currentClient.isConfigured) return remote;
    if (currentClient.canUseFallback) return fallback;
    return productionMissingConfig;
  };
  return {
    mode: () => {
      const currentClient = client();
      if (currentClient.isConfigured) return "supabase";
      return currentClient.canUseFallback ? "fallback" : "missing-config";
    },
    getQuestionAccessState: () => questionAccessState,
    listQuestions: (...args) => active().listQuestions(...args),
    getQuestionById: (...args) => active().getQuestionById(...args),
    listAlternatives: (...args) => active().listAlternatives(...args),
    listSources: (...args) => active().listSources(...args),
    listLicenses: (...args) => active().listLicenses(...args),
    listAssessments: (...args) => active().listAssessments(...args),
    getAssessmentById: (...args) => active().getAssessmentById(...args),
    createAssessment: (...args) => active().createAssessment(...args),
    createAssessmentFromBank: (...args) => active().createAssessmentFromBank(...args),
    replaceAssessmentItems: (...args) => active().replaceAssessmentItems(...args),
    updateAssessment: (...args) => active().updateAssessment(...args),
    archiveAssessment: (...args) => active().archiveAssessment(...args),
    duplicateAssessment: (...args) => active().duplicateAssessment(...args),
    addQuestionToAssessment: (...args) => active().addQuestionToAssessment(...args),
    removeQuestionFromAssessment: (...args) => active().removeQuestionFromAssessment(...args),
    reorderQuestions: (...args) => active().reorderQuestions(...args),
    updateQuestionPoints: (...args) => active().updateQuestionPoints(...args),
    registerUsage: (...args) => active().registerUsage(...args),
    getCurationHistory: (...args) => active().getCurationHistory(...args),
    generatePrintExport: (...args) => active().generatePrintExport(...args),
    createQuestionItem: (...args) => active().createQuestionItem(...args),
    adaptQuestionItem: (...args) => active().adaptQuestionItem(...args),
    updateQuestionItem: (...args) => active().updateQuestionItem(...args),
    replaceQuestionAlternatives: (...args) => active().replaceQuestionAlternatives(...args),
    setQuestionWorkflow: (...args) => active().setQuestionWorkflow(...args),
  };
})();

const initCurationBatches = () => {
  const root = document.querySelector("[data-route-screen='curadoria'] [data-batch-summary]")?.closest("#lotes");
  if (!root) return;

  const stateNode = root.querySelector("[data-curation-state]");
  const summaryNode = root.querySelector("[data-batch-summary]");
  const itemsNode = root.querySelector("[data-batch-items]");
  const detailNode = root.querySelector("[data-batch-detail]");
  const filterNode = root.querySelector("[data-batch-filter]");
  const noteNode = root.querySelector("[data-curator-note]");
  const batchCode = "EDU-001";
  const config = window.RAIZES_SUPABASE || {};
  const token = config.accessToken || localStorage.getItem("raizes:supabase-access-token") || config.anonKey;
  let batch = null;
  let items = [];
  let selectedIds = new Set();

  const setState = (message, tone = "info") => {
    if (!stateNode) return;
    stateNode.textContent = message;
    stateNode.dataset.tone = tone;
  };

  const api = async (table, params = "", options = {}) => {
    if (!config.url || !config.anonKey) {
      throw new Error("Supabase não configurado. Defina SUPABASE_URL e SUPABASE_ANON_KEY no ambiente e exponha somente valores publicos em supabase-config.js.");
    }
    const baseUrl = config.url.replace(/\/$/, "");
    const authHeaders = token && !String(token).startsWith("sb_") ? { Authorization: `Bearer ${token}` } : {};
    const response = await fetch(`${baseUrl}/rest/v1/${table}${params}`, {
      ...options,
      headers: {
        apikey: config.anonKey,
        ...authHeaders,
        "Content-Type": "application/json",
        Prefer: options.prefer || "return=representation",
        ...(options.headers || {}),
      },
    });
    if (!response.ok) {
      const body = await response.text();
      throw new Error(`${response.status} ${response.statusText}${body ? ` - ${body}` : ""}`);
    }
    if (response.status === 204) return null;
    return response.json();
  };

  const loadBatch = async () => {
    setState("Carregando lote EDU-001...", "loading");
    const batches = await api("curation_batches", `?batch_code=eq.${encodeURIComponent(batchCode)}&select=*`);
    if (!batches.length) {
      batch = null;
      items = [];
      render();
      setState("Nenhum registro encontrado para o lote EDU-001.", "empty");
      return;
    }
    batch = batches[0];
    items = await api(
      "curation_batch_items",
      `?batch_id=eq.${batch.id}&select=*,course:curated_courses(*,provider:course_providers(name,acronym),category:course_categories(name,slug))&order=created_at.asc`
    );
    render();
    setState(`Lote ${batch.batch_code} carregado do Supabase real. ${items.length} itens encontrados.`, "success");
  };

  const confidenceLabel = (item) => {
    const confidence = item.confidence || {};
    const parts = ["url", "workload", "certificate", "classification"]
      .map((key) => `${key}: ${confidence[key] || item.course?.[`${key}_confidence`] || "NAO_CONFIRMADA"}`);
    return parts.join(" · ");
  };

  const hasAlert = (item) => {
    const confidence = item.confidence || {};
    return Object.values(confidence).includes("NAO_CONFIRMADA") || Object.values(confidence).includes("MEDIA") || Boolean(item.discard_reason);
  };

  const isDuplicateCandidate = (item) => {
    const title = `${item.normalized_title || ""} ${item.course?.theme || ""}`.toLowerCase();
    return title.includes("metodologias ativas") || item.issue_type === "POSSIBLE_DUPLICATE";
  };

  const filteredItems = () => {
    const filter = filterNode?.value || "all";
    if (filter === "alerts") return items.filter(hasAlert);
    if (filter === "duplicates") return items.filter(isDuplicateCandidate);
    if (filter === "approved") return items.filter((item) => item.status === "APROVADO" || item.course?.status === "APROVADO");
    if (filter === "published") return items.filter((item) => item.status === "PUBLICADO" || item.course?.status === "PUBLICADO");
    return items;
  };

  const renderSummary = () => {
    if (!batch) {
      summaryNode.innerHTML = "";
      return;
    }
    const imported = items.filter((item) => item.course_id).length;
    const published = items.filter((item) => item.status === "PUBLICADO" || item.course?.status === "PUBLICADO").length;
    const alerts = items.filter(hasAlert).length;
    const duplicates = items.filter(isDuplicateCandidate).length;
    summaryNode.innerHTML = `
      <article><strong>${htmlEscape(batch.batch_code)}</strong><span>${htmlEscape(batch.title)}</span><small>${batch.found_count} encontrados · ${imported} importados · ${batch.discarded_count} descartados · ${published} publicados</small></article>
      <article><strong>Status</strong><span>${htmlEscape(batch.status)}</span><small>Publicação controlada por item aprovado.</small></article>
      <article><strong>Alertas</strong><span>${alerts} alertas de metadados</span><small>Use o filtro para revisar campos pendentes.</small></article>
      <article><strong>Duplicidades</strong><span>${duplicates} possiveis relacoes</span><small>Decisao editorial exigida antes de destacar.</small></article>
    `;
  };

  const renderItems = () => {
    const visible = filteredItems();
    if (!visible.length) {
      itemsNode.innerHTML = `<div class="batch-empty-state">Nenhum item corresponde ao filtro atual.</div>`;
      return;
    }
    itemsNode.innerHTML = visible
      .map((item) => {
        const course = item.course || {};
        const provider = course.provider?.acronym || course.provider?.name || item.provider_name || "Instituicao pendente";
        const category = course.category?.name || course.knowledge_center || "Categoria pendente";
        const checked = selectedIds.has(item.id) ? "checked" : "";
        const workload = course.workload_text || (course.workload_hours ? `${course.workload_hours}h` : "Carga nao confirmada");
        return `
          <article class="${hasAlert(item) ? "has-alert" : ""}">
            <label class="batch-select"><input type="checkbox" data-batch-select="${item.id}" ${checked} /><span>Selecionar</span></label>
            <div>
              <strong>${htmlEscape(item.normalized_title)}</strong>
              <span>${htmlEscape(provider)} · ${htmlEscape(category)} · ${htmlEscape(workload)} · ${htmlEscape(course.certificate_text || "Certificado em revisão")}</span>
              <small>Centro: ${htmlEscape(course.knowledge_center || category)} · Status: ${htmlEscape(item.status)} · ${htmlEscape(confidenceLabel(item))}</small>
            </div>
            <div class="batch-row-actions">
              <button type="button" data-batch-view="${item.id}">Ficha</button>
              <button type="button" data-batch-approve="${item.id}">Aprovar</button>
              <button type="button" data-batch-correction="${item.id}">Correcao</button>
              <button type="button" data-batch-reject="${item.id}">Rejeitar</button>
            </div>
          </article>
        `;
      })
      .join("");
  };

  const renderDetail = (item) => {
    if (!detailNode || !item) return;
    const course = item.course || {};
    detailNode.hidden = false;
    detailNode.innerHTML = `
      <header><span>Ficha completa</span><h3>${htmlEscape(item.normalized_title)}</h3></header>
      <div class="batch-detail-grid">
        <article><strong>Instituicao</strong><span>${htmlEscape(course.provider?.name || item.provider_name || "Pendente")}</span></article>
        <article><strong>Categoria</strong><span>${htmlEscape(course.category?.name || "Pendente")}</span></article>
        <article><strong>Centro</strong><span>${htmlEscape(course.knowledge_center || "Pendente")}</span></article>
        <article><strong>URL oficial</strong><a href="${htmlEscape(course.official_url || item.source_url)}" target="_blank" rel="noopener">Abrir origem</a></article>
        <article><strong>Coleta</strong><span>${htmlEscape(batch?.verification_date || item.created_at || "Pendente")}</span></article>
        <article><strong>Status</strong><span>${htmlEscape(item.status)}</span></article>
        <article class="span-2"><strong>Confianca</strong><span>${htmlEscape(confidenceLabel(item))}</span></article>
        <article class="span-2"><strong>Observação da curadoria</strong><span>${htmlEscape(course.curator_notes || item.action_required || "Sem observação registrada.")}</span></article>
      </div>
    `;
  };

  const render = () => {
    renderSummary();
    renderItems();
  };

  const logAction = async (item, action, previousStatus, newStatus, note) => {
    await api("curation_logs", "", {
      method: "POST",
      body: JSON.stringify({
        batch_id: batch.id,
        entity_table: "curation_batch_items",
        entity_id: item.id,
        action,
        previous_status: previousStatus,
        new_status: newStatus,
        details: { note: note || null, course_id: item.course_id || null },
      }),
    });
  };

  const updateItemStatus = async (itemId, status) => {
    const item = items.find((entry) => entry.id === itemId);
    if (!item) return;
    const note = noteNode?.value?.trim() || "";
    const previousStatus = item.status;
    await api("curation_batch_items", `?id=eq.${itemId}`, {
      method: "PATCH",
      body: JSON.stringify({ status, action_required: note || item.action_required, updated_at: new Date().toISOString() }),
    });
    if (item.course_id) {
      await api("curated_courses", `?id=eq.${item.course_id}`, {
        method: "PATCH",
        body: JSON.stringify({
          status,
          pipeline_status: status,
          curator_notes: note || item.course?.curator_notes,
          updated_at: new Date().toISOString(),
        }),
      });
    }
    await logAction(item, `CURATION_ITEM_${status}`, previousStatus, status, note);
  };

  const runSelected = async (status, onlyOne = false) => {
    const ids = Array.from(selectedIds);
    if (!ids.length) {
      setState("Selecione pelo menos um item para executar a ação.", "error");
      return;
    }
    if (onlyOne && ids.length !== 1) {
      setState("Selecione exatamente um item para publicação/despublicação controlada.", "error");
      return;
    }
    setState("Registrando ação editorial no Supabase...", "loading");
    for (const id of ids) {
      await updateItemStatus(id, status);
    }
    selectedIds = new Set();
    await loadBatch();
  };

  root.addEventListener("click", async (event) => {
    const button = event.target.closest("button");
    if (!button) return;
    try {
      if (button.hasAttribute("data-batch-refresh")) await loadBatch();
      if (button.dataset.batchView) renderDetail(items.find((item) => item.id === button.dataset.batchView));
      if (button.dataset.batchApprove) {
        await updateItemStatus(button.dataset.batchApprove, "APROVADO");
        await loadBatch();
      }
      if (button.dataset.batchCorrection) {
        await updateItemStatus(button.dataset.batchCorrection, "REVISAO_NECESSARIA");
        await loadBatch();
      }
      if (button.dataset.batchReject) {
        await updateItemStatus(button.dataset.batchReject, "REJEITADO");
        await loadBatch();
      }
      if (button.hasAttribute("data-batch-approve-selected")) await runSelected("APROVADO");
      if (button.hasAttribute("data-batch-reject-selected")) await runSelected("REJEITADO");
      if (button.hasAttribute("data-batch-correction-selected")) await runSelected("REVISAO_NECESSARIA");
      if (button.hasAttribute("data-batch-publish-selected")) await runSelected("PUBLICADO", true);
      if (button.hasAttribute("data-batch-unpublish-selected")) await runSelected("REVISAO_NECESSARIA", true);
    } catch (error) {
      setState(`Erro de permissao ou conexao: ${error.message}`, "error");
    }
  });

  root.addEventListener("change", (event) => {
    if (event.target.matches("[data-batch-select]")) {
      if (event.target.checked) selectedIds.add(event.target.dataset.batchSelect);
      else selectedIds.delete(event.target.dataset.batchSelect);
    }
    if (event.target.matches("[data-batch-filter]")) {
      renderItems();
    }
  });

  loadBatch().catch((error) => {
    summaryNode.innerHTML = "";
    itemsNode.innerHTML = `<div class="batch-empty-state">A Central de Curadoria ainda nao esta conectada ao Supabase real.</div>`;
    setState(error.message, "error");
  });
};

const initTeacherWorkspace = () => {
  const workspace = document.querySelector("[data-teacher-workspace]");
  if (!workspace) return;
  const workspaceActor = getTeacherAttendanceActor();
  const workspaceIsCurrent = () => workspaceActor === getTeacherAttendanceActor() && document.body.contains(workspace);
  const content = workspace.querySelector("[data-teacher-content]");
  const home = workspace.querySelector("[data-teacher-home]");
  const search = workspace.querySelector("[data-teacher-search]");
  if (initTeacherWorkspace.attendanceSessionGuard) {
    window.removeEventListener("storage", initTeacherWorkspace.attendanceSessionGuard);
    window.removeEventListener("focus", initTeacherWorkspace.attendanceSessionGuard);
  }
  const attendanceActor = getTeacherAttendanceActor();
  initTeacherWorkspace.attendanceSessionGuard = () => {
    if (attendanceActor === getTeacherAttendanceActor() || !document.body.contains(workspace)) return;
    ++teacherAttendanceState.revision;
    Object.assign(teacherAttendanceState, { status: "idle", records: [], key: "", promise: null, result: null, message: "", operation: null, saving: false, confirmedKey: null, confirmedRecords: null });
    teacherInstitutionalState.revision = (teacherInstitutionalState.revision || 0) + 1;
    Object.assign(teacherInstitutionalState, { status: "idle", profile: null, classes: [], schools: [], studentsByClass: {}, studentsById: {} });
    Object.assign(teacherStudentNotesState, { status: "idle", notes: [], key: "", promise: null });
    teacherDiaryState.revision += 1;
    Object.assign(teacherDiaryState, { status: "idle", entries: [], key: "", promise: null, message: "" });
    workspace.innerHTML = '<p role="alert">A sessão mudou. Recarregue a página para consultar as turmas do usuário atual.</p><a href="">Recarregar página</a>';
  };
  window.addEventListener("storage", initTeacherWorkspace.attendanceSessionGuard);
  window.addEventListener("focus", initTeacherWorkspace.attendanceSessionGuard);
  const teacherWorkspaceViewKeys = new Set(["inicio", "frequencia", "diario", "notificacoes", "calendario", "mensagens", "acesso", "perfil", "planejamentos", "turmas", "alunos", "acompanhamento", "biblioteca", "atividades", "favoritos", "experiências", "jogos", "avaliacoes", "relatorios", "formação", "universidade", "configuracoes"]);
  const getValidTeacherView = (view) => {
    const normalized = normalizeTeacherWorkspaceView(view);
    return teacherWorkspaceViewKeys.has(normalized) ? normalized : "inicio";
  };
  let activeTeacherView = getValidTeacherView(new URLSearchParams(window.location.search).get("view"));

  const getPlanningPanel = () => workspace.querySelector("[data-planning-panel]");
  const getPublicationPanel = () => workspace.querySelector("[data-publication-panel]");
  const refreshPlanningView = async ({ force = true } = {}) => {
    await ensureTeacherPlanningWeek({ force });
    const path = window.location.pathname.split("/").pop() || "";
    if (isTeacherClassPage() && getTeacherClassTab() === "semana") {
      rerenderTeacherClassPage();
      return;
    }
    if (activeTeacherView === "planejamentos" && content && document.body.contains(workspace)) {
      content.innerHTML = renderTeacherWorkspaceView("planejamentos");
    }
  };

  const fillPlanningForm = (proposal = {}, day = "segunda") => {
    const panel = getPlanningPanel();
    const form = panel?.querySelector("[data-teacher-planning-form]");
    if (!panel || !form) return;
    if (!getTeacherPlanningClasses().length) {
      window.alert("Aguarde o carregamento do vinculo institucional da turma.");
      return;
    }
    panel.hidden = false;
    panel.querySelector("h2").textContent = proposal.id ? "Editar proposta" : "Adicionar proposta";
    form.elements.id.value = proposal.id || "";
    form.elements.title.value = proposal.title || "";
    form.elements.day.value = proposal.day || day;
    form.elements.classId.value = proposal.classId || teacherPlanningState.selectedClassId || form.elements.classId.value || getTeacherPlanningClasses()[0]?.id || "";
    if (form.elements.startTime) form.elements.startTime.value = proposal.startTime ? proposal.startTime.slice(0, 5) : "";
    form.elements.resourceType.value = proposal.resourceType || "proposta-livre";
    form.elements.note.value = proposal.note || "";
    form.elements.title.focus();
  };

  const closePlanningForm = () => {
    const panel = getPlanningPanel();
    const form = panel?.querySelector("[data-teacher-planning-form]");
    if (!panel || !form) return;
    form.reset();
    form.elements.id.value = "";
    panel.hidden = true;
    panel.querySelector("h2").textContent = "Adicionar proposta";
  };

  const fillPublicationForm = (proposal) => {
    const panel = getPublicationPanel();
    const form = panel?.querySelector("[data-teacher-publication-form]");
    if (!panel || !form || !proposal) return;
    const publication = proposal.publication || {};
    panel.hidden = false;
    panel.querySelector("h2").textContent = publication.id ? "Editar publicação" : "Publicar na agenda";
    form.elements.planId.value = proposal.id;
    form.elements.publicationId.value = publication.id || "";
    form.elements.title.value = publication.title || proposal.title || "";
    form.elements.entryDate.value = publication.entry_date || proposal.planDate || "";
    form.elements.startTime.value = publication.start_time ? publication.start_time.slice(0, 5) : "";
    form.elements.endTime.value = publication.end_time ? publication.end_time.slice(0, 5) : "";
    form.elements.entryType.value = publication.entry_type || normalizeTeacherPlanningCalendarType(proposal.resourceType);
    form.elements.description.value = publication.description || "";
    form.elements.title.focus();
  };

  const closePublicationForm = () => {
    const panel = getPublicationPanel();
    const form = panel?.querySelector("[data-teacher-publication-form]");
    if (!panel || !form) return;
    form.reset();
    form.elements.planId.value = "";
    form.elements.publicationId.value = "";
    panel.hidden = true;
    panel.querySelector("h2").textContent = "Publicar na agenda";
  };

  const openView = (view, { updateUrl = true } = {}) => {
    const normalizedView = getValidTeacherView(view);
    if (!content) {
      if (!updateUrl) return;
      const params = new URLSearchParams({ view: normalizedView });
      const selectedSchool = getTeacherSelectedSchoolId();
      if (selectedSchool) params.set("school", selectedSchool);
      if (normalizedView === "mensagens") {
        const page = document.querySelector("[data-app-page]")?.dataset.appPage;
        const id = getPrintableParams().get("id") || "";
        const classId = page === "professorTurma" ? id
          : page === "professorAluno" ? teacherInstitutionalState.studentsById?.[id]?.classId : "";
        if (getTeacherInstitutionalClasses().some(item => item.id === classId)) params.set("message_class_id", classId);
      }
      window.location.assign(`/professor.html?${params.toString()}`);
      return;
    }
    activeTeacherView = normalizedView;
    if (updateUrl) {
      const params = new URLSearchParams(window.location.search);
      if (normalizedView === "inicio") params.delete("view");
      else params.set("view", normalizedView);
      const nextUrl = `${window.location.pathname}${params.toString() ? `?${params.toString()}` : ""}`;
      if (nextUrl !== `${window.location.pathname}${window.location.search}`) window.history.pushState({}, "", nextUrl);
    }
    if (normalizedView === "inicio") {
      content.hidden = true;
      if (home) home.hidden = false;
    } else {
      content.hidden = false;
      if (home) home.hidden = true;
    }
    content.innerHTML = renderTeacherWorkspaceView(normalizedView);
    workspace.querySelectorAll("[data-teacher-view]").forEach((button) => {
      button.classList.toggle("is-active", getValidTeacherView(button.dataset.teacherView) === normalizedView);
    });
    initUniversalActivityTeacherDeliveries();
    initPrintableActivities();
    initTeacherAvaliaApplication();
    bindOfficialReportControls(workspace, "teacher");
    if (search) search.value = "";
    if (normalizedView === "planejamentos") {
      ensureTeacherPlanningWeek().then(() => {
        if (activeTeacherView === "planejamentos" && content && document.body.contains(workspace)) {
          content.innerHTML = renderTeacherWorkspaceView("planejamentos");
        }
      });
    }
    if (normalizedView === "acompanhamento") {
      ensureTeacherTrackingBundle({ force: true }).then(() => {
        if (activeTeacherView === "acompanhamento" && content && document.body.contains(workspace)) {
          content.innerHTML = renderTeacherWorkspaceView("acompanhamento");
        }
      });
    }
    if (normalizedView === "relatorios") {
      const before = `${officialReportsState.teacher.status}:${officialReportsState.teacher.key}`;
      ensureTeacherOfficialReport().then(() => {
        const after = `${officialReportsState.teacher.status}:${officialReportsState.teacher.key}`;
        if (before !== after && activeTeacherView === "relatorios" && content && document.body.contains(workspace)) {
          content.innerHTML = renderTeacherWorkspaceView("relatorios");
          bindOfficialReportControls(workspace, "teacher");
        }
      });
      const historyBefore = `${officialReportsState.teacher.historyStatus}:${officialReportsState.teacher.history?.length || 0}`;
      ensureOfficialReportHistory("teacher").then(() => {
        const historyAfter = `${officialReportsState.teacher.historyStatus}:${officialReportsState.teacher.history?.length || 0}`;
        if (historyBefore !== historyAfter && activeTeacherView === "relatorios" && content && document.body.contains(workspace)) {
          content.innerHTML = renderTeacherWorkspaceView("relatorios");
          bindOfficialReportControls(workspace, "teacher");
        }
      });
    }
  };

  const rerenderTeacherClassPage = () => {
    if (!workspaceIsCurrent()) return;
    const currentWorkspace = workspace;
    if (!document.body.contains(currentWorkspace)) return;
    currentWorkspace.outerHTML = renderTeacherClassPage();
    requestAnimationFrame(() => document.querySelector(".teacher-workspace")?.classList.add("is-mounted"));
    initTeacherWorkspace();
  };

  const rerenderTeacherStudentPage = () => {
    if (!workspaceIsCurrent()) return;
    const currentWorkspace = workspace;
    if (!document.body.contains(currentWorkspace)) return;
    currentWorkspace.outerHTML = renderTeacherStudentPage();
    requestAnimationFrame(() => document.querySelector(".teacher-workspace")?.classList.add("is-mounted"));
    initTeacherWorkspace();
  };

  const hydrateTeacherAttendanceIfNeeded = async ({ force = false } = {}) => {
    if (!workspaceIsCurrent() || teacherAttendanceState.saving || !isTeacherClassPage() || getTeacherClassTab() !== "frequencia" || teacherInstitutionalState.status !== "ready") return;
    const classId = getTeacherAttendanceClassId(), date = getTeacherAttendanceDate(), route = getTeacherAttendanceRoute();
    if (!classId || !date) return;
    const key = getTeacherAttendanceKey(classId, date);
    if (!force && teacherAttendanceState.key === key && ["ready", "error"].includes(teacherAttendanceState.status)) return;
    const pending = ensureTeacherAttendanceDay({ force, classId, date });
    const revision = teacherAttendanceState.revision;
    await pending;
    if (!workspaceIsCurrent() || teacherAttendanceState.saving || revision !== teacherAttendanceState.revision || teacherAttendanceState.key !== key || route !== getTeacherAttendanceRoute()) return;
    rerenderTeacherClassPage();
  };

  workspace.addEventListener("click", async (event) => {
    const urlButton = event.target.closest("[data-teacher-open-url]");
    if (urlButton) {
      window.location.href = urlButton.dataset.teacherOpenUrl;
      return;
    }
    const classTab = event.target.closest("[data-teacher-class-tab]");
    if (classTab) {
      event.preventDefault();
      const params = new URLSearchParams(window.location.search);
      params.set("tab", classTab.dataset.teacherClassTab || "alunos");
      if (classTab.dataset.classId) params.set("id", classTab.dataset.classId);
      window.location.href = `${window.location.pathname}?${params.toString()}`;
      return;
    }
    const publishClassWeek = event.target.closest("[data-class-week-publish]");
    if (publishClassWeek) {
      event.preventDefault();
      const classItem = getTeacherInstitutionalClasses().find((item) => item.id === publishClassWeek.dataset.classWeekPublish);
      if (!classItem) return;
      if (!window.confirm(`Publicar ou atualizar Minha Semana de ${classItem.name}?`)) return;
      publishClassWeek.disabled = true;
      publishClassWeek.textContent = "PUBLICANDO...";
      try {
        await publishTeacherClassWeekToSupabase(classItem.id);
        rerenderTeacherClassPage();
      } catch (error) {
        window.alert(error.message || "Não foi possível publicar Minha Semana.");
      } finally {
        publishClassWeek.disabled = false;
      }
      return;
    }
    const reloadAttendance = event.target.closest("[data-attendance-reload]");
    if (reloadAttendance) {
      if (teacherAttendanceState.saving) return;
      if (!window.confirm("Recarregar descarta alterações ainda não salvas. Continuar?")) return;
      await hydrateTeacherAttendanceIfNeeded({ force: true });
      return;
    }
    const markAll = event.target.closest("[data-attendance-mark-all]");
    if (markAll) {
      event.preventDefault();
      if (teacherAttendanceState.saving || !window.confirm("Marcar todos os alunos exibidos como presentes? Revise antes de salvar.")) return;
      workspace.querySelectorAll(".tw-attendance-row").forEach((row) => {
        row.querySelector("input[value='present']").checked = true;
        row.querySelectorAll(".tw-attendance-choice").forEach((choice) => {
          choice.classList.toggle("is-selected", choice.querySelector("input")?.value === "present");
        });
      });
      return;
    }
    const button = event.target.closest("[data-teacher-view]");
    const addPlanning = event.target.closest("[data-planning-add]");
    if (addPlanning) {
      event.preventDefault();
      fillPlanningForm({}, addPlanning.dataset.planningAdd || "segunda");
      return;
    }
    const cancelPlanning = event.target.closest("[data-planning-cancel]");
    if (cancelPlanning) {
      event.preventDefault();
      closePlanningForm();
      return;
    }
    const viewPlanning = event.target.closest("[data-planning-view]");
    if (viewPlanning) {
      event.preventDefault();
      const detail = workspace.querySelector(`[data-planning-detail="${CSS.escape(viewPlanning.dataset.planningView)}"]`);
      if (detail) detail.hidden = !detail.hidden;
      return;
    }
    const editPlanning = event.target.closest("[data-planning-edit]");
    if (editPlanning) {
      event.preventDefault();
      const proposal = (teacherPlanningState.plans || []).find((item) => item.id === editPlanning.dataset.planningEdit);
      if (proposal) fillPlanningForm(proposal, proposal.day);
      return;
    }
    const finalizePlanning = event.target.closest("[data-planning-finalize]");
    if (finalizePlanning) {
      event.preventDefault();
      const proposal = (teacherPlanningState.plans || []).find((item) => item.id === finalizePlanning.dataset.planningFinalize);
      if (!proposal) return;
      if (!window.confirm(`Finalizar o planejamento "${proposal.title}"?`)) return;
      finalizePlanning.disabled = true;
      finalizePlanning.textContent = "FINALIZANDO...";
      try {
        await finalizeTeacherPlanning(proposal.id);
        await refreshPlanningView({ force: false });
      } catch (error) {
        window.alert(error.message || "Não foi possível finalizar o planejamento.");
      } finally {
        finalizePlanning.disabled = false;
      }
      return;
    }
    const publishPlanning = event.target.closest("[data-planning-publish]");
    if (publishPlanning) {
      event.preventDefault();
      const proposal = (teacherPlanningState.plans || []).find((item) => item.id === publishPlanning.dataset.planningPublish);
      if (proposal) fillPublicationForm(proposal);
      return;
    }
    const cancelPublication = event.target.closest("[data-publication-cancel]");
    if (cancelPublication) {
      event.preventDefault();
      closePublicationForm();
      return;
    }
    const unpublishPlanning = event.target.closest("[data-planning-unpublish]");
    if (unpublishPlanning) {
      event.preventDefault();
      const proposal = (teacherPlanningState.plans || []).find((item) => item.id === unpublishPlanning.dataset.planningUnpublish);
      if (!proposal) return;
      if (!window.confirm(`Retirar "${proposal.title}" da agenda da turma?`)) return;
      unpublishPlanning.disabled = true;
      unpublishPlanning.textContent = "RETIRANDO...";
      try {
        await archiveTeacherCalendarEntry(proposal.id);
        await refreshPlanningView({ force: false });
      } catch (error) {
        window.alert(error.message || "Não foi possível retirar a publicação.");
      } finally {
        unpublishPlanning.disabled = false;
      }
      return;
    }
    const removePlanning = event.target.closest("[data-planning-remove]");
    if (removePlanning) {
      event.preventDefault();
      const proposal = (teacherPlanningState.plans || []).find((item) => item.id === removePlanning.dataset.planningRemove);
      if (!proposal) return;
      const message = proposal.published
        ? `Arquivar a proposta "${proposal.title}" e retirar a publicação ativa da agenda?`
        : `Arquivar a proposta "${proposal.title}" do planejamento?`;
      if (!window.confirm(message)) return;
      removePlanning.disabled = true;
      removePlanning.textContent = "ARQUIVANDO...";
      try {
        await archiveTeacherPlanning(proposal.id);
        await refreshPlanningView({ force: false });
      } catch (error) {
        window.alert(error.message || "Não foi possível arquivar a proposta.");
      } finally {
        removePlanning.disabled = false;
      }
      return;
    }
    const weekMove = event.target.closest("[data-planning-week-move]");
    if (weekMove) {
      event.preventDefault();
      const current = fromTeacherIsoDate(teacherPlanningState.weekStartIso || getTeacherPlanningWeekStart());
      current.setDate(current.getDate() + Number(weekMove.dataset.planningWeekMove || 0) * 7);
      teacherPlanningState.weekStartIso = toTeacherIsoDate(current);
      await refreshPlanningView({ force: true });
      return;
    }
    const weekToday = event.target.closest("[data-planning-week-today]");
    if (weekToday) {
      event.preventDefault();
      teacherPlanningState.weekStartIso = getTeacherPlanningWeekStart();
      await refreshPlanningView({ force: true });
      return;
    }
    const messageWeekMove = event.target.closest("[data-teacher-message-week-move]");
    if (messageWeekMove) {
      event.preventDefault();
      const current = fromTeacherIsoDate(teacherClassMessagesState.weekStartIso || getTeacherPlanningWeekStart());
      current.setDate(current.getDate() + Number(messageWeekMove.dataset.teacherMessageWeekMove || 0) * 7);
      teacherClassMessagesState.weekStartIso = toTeacherIsoDate(current);
      await ensureTeacherClassMessages({ force: true });
      if (activeTeacherView === "mensagens" && content && document.body.contains(workspace)) {
        content.innerHTML = renderTeacherWorkspaceView("mensagens");
      }
      return;
    }
    const messageWeekToday = event.target.closest("[data-teacher-message-week-today]");
    if (messageWeekToday) {
      event.preventDefault();
      teacherClassMessagesState.weekStartIso = getTeacherPlanningWeekStart();
      await ensureTeacherClassMessages({ force: true });
      if (activeTeacherView === "mensagens" && content && document.body.contains(workspace)) {
        content.innerHTML = renderTeacherWorkspaceView("mensagens");
      }
      return;
    }
    const messageView = event.target.closest("[data-teacher-message-view]");
    if (messageView) {
      event.preventDefault();
      const message = (teacherClassMessagesState.messages || []).find((item) => item.id === messageView.dataset.teacherMessageView);
      if (message) window.alert(`${message.title}\n\n${message.text}`);
      return;
    }
    const messageStatus = event.target.closest("[data-teacher-message-status]");
    if (messageStatus) {
      event.preventDefault();
      const message = (teacherClassMessagesState.messages || []).find((item) => item.id === messageStatus.dataset.teacherMessageStatus);
      if (!message) return;
      const toStatus = messageStatus.dataset.toStatus || "";
      const destination = messageStatus.dataset.destination || (message.audienceType === "student" ? `Aluno/Família: ${message.studentName}` : `Toda a turma: ${message.className}`);
      const label = toStatus === "published" ? `Publicar novamente para ${destination}?` : `Retirar "${message.title}" da publicação?`;
      if (!window.confirm(label)) return;
      messageStatus.disabled = true;
      messageStatus.textContent = toStatus === "published" ? "PUBLICANDO..." : "RETIRANDO...";
      try {
        await setTeacherClassMessageStatus(message.id, toStatus);
        rerenderTeacherClassPage();
      } catch (error) {
        window.alert(error.message || "Não foi possível alterar o recado.");
      }
      return;
    }
    const messageDelete = event.target.closest("[data-teacher-message-delete]");
    if (messageDelete) {
      event.preventDefault();
      const message = (teacherClassMessagesState.messages || []).find((item) => item.id === messageDelete.dataset.teacherMessageDelete);
      if (!message) return;
      if (!window.confirm("Excluir este recado definitivamente?")) return;
      messageDelete.disabled = true;
      messageDelete.textContent = "EXCLUINDO...";
      try {
        await deleteTeacherClassMessage(message.id);
        rerenderTeacherClassPage();
      } catch (error) {
        window.alert(error.message || "Não foi possível excluir o recado.");
      }
      return;
    }
    const recommendationStatus = event.target.closest("[data-teacher-recommendation-status]");
    if (recommendationStatus) {
      event.preventDefault();
      const recommendation = (teacherRecommendationsState.items || []).find((item) => item.id === recommendationStatus.dataset.teacherRecommendationStatus);
      if (!recommendation) return;
      const toStatus = recommendationStatus.dataset.toStatus || "";
      const destination = recommendationStatus.dataset.destination || (recommendation.targetType === "student" ? `Aluno/Família: ${recommendation.studentName}` : `Toda a turma: ${recommendation.className}`);
      const label = toStatus === "published" ? `Publicar novamente para ${destination}?` : `Retirar "${recommendation.contentTitle}" da publicação?`;
      if (!window.confirm(label)) return;
      recommendationStatus.disabled = true;
      recommendationStatus.textContent = toStatus === "published" ? "PUBLICANDO..." : "RETIRANDO...";
      try {
        await setTeacherRecommendationStatus(recommendation.id, toStatus);
        rerenderTeacherClassPage();
      } catch (error) {
        window.alert(error.message || "Não foi possível alterar a recomendação.");
      }
      return;
    }
    const recommendationDelete = event.target.closest("[data-teacher-recommendation-delete]");
    if (recommendationDelete) {
      event.preventDefault();
      const recommendation = (teacherRecommendationsState.items || []).find((item) => item.id === recommendationDelete.dataset.teacherRecommendationDelete);
      if (!recommendation) return;
      if (!window.confirm("Excluir esta recomendação definitivamente da operação?")) return;
      recommendationDelete.disabled = true;
      recommendationDelete.textContent = "EXCLUINDO...";
      try {
        await deleteTeacherRecommendation(recommendation.id);
        rerenderTeacherClassPage();
      } catch (error) {
        window.alert(error.message || "Não foi possível excluir a recomendação.");
      }
      return;
    }
    const diaryClose = event.target.closest("[data-teacher-diary-close]");
    if (diaryClose) {
      event.preventDefault();
      const entryId = diaryClose.dataset.teacherDiaryClose || "";
      if (!entryId) return;
      if (!window.confirm("Fechar este Diário de Classe? Depois do fechamento, a edição fica bloqueada nesta versão.")) return;
      diaryClose.disabled = true;
      diaryClose.textContent = "FECHANDO...";
      try {
        await closeTeacherDiaryEntry(entryId);
        rerenderTeacherClassPage();
      } catch (error) {
        window.alert(error.message || "Não foi possível fechar o Diário de Classe.");
      }
      return;
    }
    const trackingStudentPick = event.target.closest("[data-tracking-student-pick]");
    if (trackingStudentPick) {
      event.preventDefault();
      teacherTrackingState.selectedStudentId = trackingStudentPick.dataset.trackingStudentPick || "";
      const params = new URLSearchParams(window.location.search);
      params.set("view", "acompanhamento");
      params.set("class", teacherTrackingState.selectedClassId || getTeacherTrackingClassId());
      params.set("student", teacherTrackingState.selectedStudentId);
      window.history.replaceState({}, "", `${window.location.pathname}?${params.toString()}`);
      if (activeTeacherView === "acompanhamento" && content && document.body.contains(workspace)) {
        content.innerHTML = renderTeacherWorkspaceView("acompanhamento");
      }
      return;
    }
    if (!button) return;
    event.preventDefault();
    openView(button.dataset.teacherView || "inicio");
  });

  workspace.addEventListener("submit", async (event) => {
    const form = event.target.closest("[data-teacher-planning-form]");
    const publicationForm = event.target.closest("[data-teacher-publication-form]");
    const messageForm = event.target.closest("[data-teacher-family-message-form]");
    const attendanceForm = event.target.closest("[data-teacher-attendance-form]");
    const diaryForm = event.target.closest("[data-teacher-diary-form]");
    const diaryPeriodForm = event.target.closest("[data-teacher-diary-period-form]");
    const studentNoteForm = event.target.closest("[data-teacher-student-note-form]");
    if (!form && !publicationForm && !messageForm && !attendanceForm && !diaryForm && !diaryPeriodForm && !studentNoteForm) return;
    event.preventDefault();
    const submitButton = (form || publicationForm || messageForm || attendanceForm || diaryForm || diaryPeriodForm || studentNoteForm).querySelector("button[type='submit']");
    const previousLabel = submitButton?.textContent || "";
    if (submitButton) {
      submitButton.disabled = true;
      submitButton.textContent = form || attendanceForm || diaryForm || studentNoteForm ? "SALVANDO..." : publicationForm ? "PUBLICANDO..." : "ATUALIZANDO...";
    }
    try {
      if (form) {
        await saveTeacherPlanningToSupabase(new FormData(form));
        closePlanningForm();
      }
      if (publicationForm) {
        await saveTeacherCalendarEntryToSupabase(new FormData(publicationForm));
        closePublicationForm();
      }
      if (messageForm) {
        const data = new FormData(messageForm);
        teacherClassMessagesState.classId = String(data.get("classId") || teacherClassMessagesState.classId || "");
        await sendTeacherClassMessage(data);
        messageForm.reset();
        rerenderTeacherClassPage();
        return;
      }
      if (attendanceForm) {
        const data = new FormData(attendanceForm);
        const classId = attendanceForm.dataset.classId || getTeacherAttendanceClassId();
        const date = String(data.get("attendanceDate") || getTeacherAttendanceDate()), route = getTeacherAttendanceRoute();
        if (attendanceForm.dataset.attendanceKey !== getTeacherAttendanceKey(classId, date)) throw new Error("A sessão mudou. Recarregue a página antes de registrar frequência.");
        const records = collectTeacherAttendanceChanges(data, getTeacherInstitutionalStudents(classId));
        await saveTeacherAttendanceDay({ classId, date, records });
        if (!workspaceIsCurrent() || !document.body.contains(attendanceForm) || route !== getTeacherAttendanceRoute()) return;
        const params = new URLSearchParams(window.location.search);
        params.set("id", classId); params.set("tab", "frequencia"); params.set("date", date);
        window.history.replaceState({}, "", `${window.location.pathname}?${params.toString()}`);
        rerenderTeacherClassPage();
        return;
      }
      if (diaryForm) {
        await saveTeacherDiaryEntry(new FormData(diaryForm));
        rerenderTeacherClassPage();
        return;
      }
      if (diaryPeriodForm) {
        const data = new FormData(diaryPeriodForm);
        const params = new URLSearchParams(window.location.search);
        params.set("tab", "diario");
        params.set("diaryFrom", String(data.get("diaryFrom") || ""));
        params.set("diaryTo", String(data.get("diaryTo") || ""));
        window.location.href = `${window.location.pathname}?${params.toString()}`;
        return;
      }
      if (studentNoteForm) {
        const data = new FormData(studentNoteForm);
        await saveTeacherStudentNote(data);
        rerenderTeacherStudentPage();
        return;
      }
      if (form || publicationForm) await refreshPlanningView({ force: false });
      if (messageForm && activeTeacherView === "mensagens" && content && document.body.contains(workspace)) {
        content.innerHTML = renderTeacherWorkspaceView("mensagens");
      }
    } catch (error) {
      if (attendanceForm && !workspaceIsCurrent()) return;
      window.alert(error.message || "Não foi possível salvar no Supabase.");
    } finally {
      if (submitButton) {
        submitButton.disabled = false;
        submitButton.textContent = previousLabel;
        if (attendanceForm && workspaceIsCurrent()) syncTeacherAttendanceControls();
      }
    }
  });

  workspace.addEventListener("change", async (event) => {
    const schoolSelector = event.target.closest("[data-teacher-school-selector]");
    if (schoolSelector) {
      const params = new URLSearchParams({ view: activeTeacherView });
      params.set("school", schoolSelector.value || "");
      window.location.assign(`professor.html?${params.toString()}`);
      return;
    }
    const planningClassSelect = event.target.closest("[data-planning-class]");
    if (planningClassSelect) {
      teacherPlanningState.selectedClassId = planningClassSelect.value || "";
      await refreshPlanningView({ force: false });
      return;
    }
    const trackingClassSelect = event.target.closest("[data-tracking-class]");
    if (trackingClassSelect) {
      teacherTrackingState.selectedClassId = trackingClassSelect.value || "";
      teacherTrackingState.selectedStudentId = "";
      const params = new URLSearchParams(window.location.search);
      params.set("view", "acompanhamento");
      params.set("class", teacherTrackingState.selectedClassId);
      params.delete("student");
      window.history.replaceState({}, "", `${window.location.pathname}?${params.toString()}`);
      await ensureTeacherTrackingBundle({ force: true });
      if (activeTeacherView === "acompanhamento" && content && document.body.contains(workspace)) {
        content.innerHTML = renderTeacherWorkspaceView("acompanhamento");
      }
      return;
    }
    const trackingStudentSelect = event.target.closest("[data-tracking-student]");
    if (trackingStudentSelect) {
      teacherTrackingState.selectedStudentId = trackingStudentSelect.value || "";
      const params = new URLSearchParams(window.location.search);
      params.set("view", "acompanhamento");
      params.set("class", teacherTrackingState.selectedClassId || getTeacherTrackingClassId());
      params.set("student", teacherTrackingState.selectedStudentId);
      window.history.replaceState({}, "", `${window.location.pathname}?${params.toString()}`);
      if (activeTeacherView === "acompanhamento" && content && document.body.contains(workspace)) {
        content.innerHTML = renderTeacherWorkspaceView("acompanhamento");
      }
      return;
    }
    const trackingPeriodSelect = event.target.closest("[data-tracking-period]");
    if (trackingPeriodSelect) {
      teacherTrackingState.periodDays = [7, 30, 90].includes(Number(trackingPeriodSelect.value)) ? Number(trackingPeriodSelect.value) : 30;
      const params = new URLSearchParams(window.location.search);
      params.set("view", "acompanhamento");
      params.set("class", teacherTrackingState.selectedClassId || getTeacherTrackingClassId());
      params.set("period", String(teacherTrackingState.periodDays));
      if (teacherTrackingState.selectedStudentId) params.set("student", teacherTrackingState.selectedStudentId);
      window.history.replaceState({}, "", `${window.location.pathname}?${params.toString()}`);
      await ensureTeacherTrackingBundle({ force: true });
      if (activeTeacherView === "acompanhamento" && content && document.body.contains(workspace)) {
        content.innerHTML = renderTeacherWorkspaceView("acompanhamento");
      }
      return;
    }
    const attendanceRadio = event.target.closest(".tw-attendance-choice input[type='radio']");
    if (attendanceRadio) {
      const row = attendanceRadio.closest(".tw-attendance-row");
      row?.querySelectorAll(".tw-attendance-choice").forEach((choice) => {
        choice.classList.toggle("is-selected", choice.querySelector("input")?.checked === true);
      });
      return;
    }
    const attendanceDate = event.target.closest("[data-teacher-attendance-date]");
    if (attendanceDate) {
      const params = new URLSearchParams(window.location.search);
      params.set("date", attendanceDate.value || getTeacherAttendanceDate());
      params.set("tab", "frequencia");
      window.location.href = `${window.location.pathname}?${params.toString()}`;
      return;
    }
    const diaryDate = event.target.closest("[data-teacher-diary-date]");
    if (diaryDate) {
      const params = new URLSearchParams(window.location.search);
      params.set("diaryDate", diaryDate.value || getTeacherDiaryDate());
      params.set("tab", "diario");
      window.location.href = `${window.location.pathname}?${params.toString()}`;
      return;
    }
    const classSelect = event.target.closest("[data-teacher-family-message-form] select[name='classId']");
    const messageAudience = event.target.closest("[data-teacher-message-audience]");
    if (messageAudience) {
      const form = messageAudience.closest("[data-teacher-family-message-form]");
      const wrap = form?.querySelector("[data-teacher-message-student-wrap]");
      if (wrap) wrap.hidden = messageAudience.value !== "student";
      return;
    }
    if (!classSelect) return;
    teacherClassMessagesState.classId = classSelect.value || "";
    await ensureTeacherClassMessages({ force: true, classId: teacherClassMessagesState.classId });
    if (activeTeacherView === "mensagens" && content && document.body.contains(workspace)) {
      content.innerHTML = renderTeacherWorkspaceView("mensagens");
    }
  });

  search?.addEventListener("input", () => {
    const query = search.value.trim().toLowerCase();
    content?.querySelectorAll("[data-teacher-search-item]").forEach((item) => {
      item.hidden = Boolean(query) && !item.textContent.toLowerCase().includes(query);
    });
  });

  if (initTeacherWorkspace.onPopState) window.removeEventListener("popstate", initTeacherWorkspace.onPopState);
  initTeacherWorkspace.onPopState = () => {
    if (content && document.body.contains(workspace)) openView(new URLSearchParams(window.location.search).get("view"), { updateUrl: false });
  };
  window.addEventListener("popstate", initTeacherWorkspace.onPopState);
  if (activeTeacherView !== "inicio") {
    openView(activeTeacherView, { updateUrl: false });
  }

  ensureTeacherInstitutionalData().then(() => {
    if (teacherInstitutionalState.hydratedDom || !workspaceIsCurrent()) return;
    teacherInstitutionalState.hydratedDom = true;
    const path = window.location.pathname.split("/").pop() || "professor.html";
    if (isTeacherClassPage()) {
      const classId = getPrintableParams().get("id") || getTeacherInstitutionalClasses()[0]?.id || "";
      if (getTeacherClassTab() === "semana") {
        teacherPlanningState.status = "idle";
        ensureTeacherPlanningWeek({ force: true }).then(rerenderTeacherClassPage);
      }
      if (getTeacherClassTab() === "recados") {
        teacherClassMessagesState.classId = classId;
        teacherClassMessagesState.status = "idle";
        ensureTeacherClassMessages({ force: true, classId }).then(rerenderTeacherClassPage);
      }
      if (getTeacherClassTab() === "recomendacoes") {
        teacherRecommendationsState.classId = classId;
        teacherRecommendationsState.status = "idle";
        ensureTeacherRecommendations({ force: true, classId }).then(rerenderTeacherClassPage);
      }
      if (getTeacherClassTab() === "diario") {
        const date = getTeacherDiaryDate();
        teacherPlanningState.status = "idle";
        const range = getTeacherDiaryPeriodRange();
        ensureTeacherPlanningWeek({ force: true })
          .then(() => ensureTeacherAttendanceDay({ force: true, classId, date }))
          .then(() => ensureTeacherDiaryEntries({ force: true, classId, date }))
          .then(() => ensureTeacherDiaryPeriodSummary({ force: true, classId, from: range.from, to: range.to }))
          .then(rerenderTeacherClassPage);
        // Keep the captured workspace mounted until hydration finishes. Replacing it
        // here makes the guarded completion callback discard its own result.
        return;
      }
      workspace.outerHTML = renderTeacherClassPage();
      requestAnimationFrame(() => document.querySelector(".teacher-workspace")?.classList.add("is-mounted"));
      initTeacherWorkspace();
      return;
    }
    if (path === "professor-aluno.html") {
      const studentId = getPrintableParams().get("id") || "";
      const student = teacherInstitutionalState.studentsById?.[studentId] || null;
      const classId = student?.classId || "";
      if (studentId && classId) {
        ensureTeacherStudentNotes({ force: true, classId, studentId })
          .then(() => ensureTeacherDiaryEntries({ force: true, classId, date: getTeacherDiaryDate() }))
          .then(rerenderTeacherStudentPage);
      }
      workspace.outerHTML = renderTeacherStudentPage();
      requestAnimationFrame(() => document.querySelector(".teacher-workspace")?.classList.add("is-mounted"));
      initTeacherWorkspace();
      return;
    }
    workspace.outerHTML = renderTeacherPilotHome();
    requestAnimationFrame(() => document.querySelector(".teacher-workspace")?.classList.add("is-mounted"));
    initTeacherWorkspace();
  });

  hydrateTeacherAttendanceIfNeeded();
};

const initStudentInstitutionalDashboard = () => {
  const dashboard = document.querySelector("[data-student-dashboard]");
  if (!dashboard || !isStudentInstitutionalMode()) return;
  initStudentHomeSearch(dashboard);
  dashboard.addEventListener("click", async (event) => {
    const scheduleEditButton = event.target.closest?.("[data-student-schedule-edit]");
    if (scheduleEditButton) {
      event.preventDefault();
      studentPersonalScheduleDraft = getStudentPersonalSchedule();
      studentPersonalScheduleEditing = true;
      dashboard.outerHTML = renderStudentSimpleDashboard();
      initStudentInstitutionalDashboard();
      initStudentAvaliaApplication();
      return;
    }
    const scheduleCancelButton = event.target.closest?.("[data-student-schedule-cancel]");
    if (scheduleCancelButton) {
      event.preventDefault();
      studentPersonalScheduleDraft = null;
      studentPersonalScheduleEditing = false;
      dashboard.outerHTML = renderStudentSimpleDashboard();
      initStudentInstitutionalDashboard();
      initStudentAvaliaApplication();
      return;
    }
    const readButton = event.target.closest?.("[data-student-delivery-read]");
    if (!readButton) return;
    event.preventDefault();
    readButton.disabled = true;
    readButton.textContent = "Marcando...";
    try {
      await markCommunicationDeliveryRead(readButton.dataset.studentDeliveryRead || "", ["aluno", "admin"]);
      await ensureStudentInstitutionalData({ force: true });
      if (!document.body.contains(dashboard)) return;
      dashboard.outerHTML = renderStudentSimpleDashboard();
      initStudentInstitutionalDashboard();
      initStudentAvaliaApplication();
    } catch (error) {
      window.alert(error.message || "Não foi possível marcar o comunicado como lido.");
      readButton.disabled = false;
      readButton.textContent = "Marcar como lido";
    }
  });
  dashboard.addEventListener("submit", async (event) => {
    const form = event.target.closest?.("[data-student-schedule-form]");
    if (!form) return;
    event.preventDefault();
    const saveButton = dashboard.querySelector("[data-student-schedule-save]");
    if (saveButton) {
      saveButton.disabled = true;
      saveButton.textContent = "Salvando...";
    }
    try {
      const saved = await saveStudentPersonalSchedule(collectStudentPersonalScheduleForm(form));
      studentInstitutionalState.personalSchedule = saved;
      studentInstitutionalState.personalScheduleError = "";
      studentPersonalScheduleDraft = null;
      studentPersonalScheduleEditing = false;
      dashboard.outerHTML = renderStudentSimpleDashboard();
      initStudentInstitutionalDashboard();
      initStudentAvaliaApplication();
    } catch (error) {
      studentInstitutionalState.personalScheduleError = error.message || "Não foi possível salvar o horário de aula.";
      studentPersonalScheduleDraft = normalizeStudentPersonalSchedulePayload({ slots: collectStudentPersonalScheduleForm(form) });
      dashboard.outerHTML = renderStudentSimpleDashboard();
      initStudentInstitutionalDashboard();
      initStudentAvaliaApplication();
    }
  });
  ensureStudentInstitutionalData().then(() => {
    if (studentInstitutionalState.hydratedDom || !document.body.contains(dashboard)) return;
    studentInstitutionalState.hydratedDom = true;
    dashboard.outerHTML = renderStudentSimpleDashboard();
    requestAnimationFrame(() => {
      document.querySelector("[data-student-dashboard]")?.classList.add("is-mounted");
      initStudentAvaliaApplication();
    });
    initStudentInstitutionalDashboard();
  });
};

const initStudentHomeSearch = (root = document) => {
  const input = root.querySelector("[data-student-premium-search]");
  const results = root.querySelector("[data-student-premium-search-results]");
  if (!input || !results || input.dataset.studentSearchBound === "true") return;
  input.dataset.studentSearchBound = "true";
  const render = () => {
    const html = renderStudentHomeSearchResults(input.value || "");
    results.innerHTML = html;
    results.hidden = !html;
  };
  input.addEventListener("input", render);
  input.addEventListener("focus", render);
  input.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      input.value = "";
      render();
      input.blur();
    }
  });
  root.addEventListener("click", (event) => {
    if (event.target.closest?.(".student-premium-search")) return;
    results.hidden = true;
  });
};

